window.AARTI_DATA = {"deities":[{"id":"ganesh","n":"Ganesh","d":"श्री गणेश","ini":"ग","c":"#C2410C","aka":["ganesh","ganesha","ganpati","ganapati","vinayak","vinayaka","vighnaharta","gajanan","lambodar","ekdant","bappa"],"akaD":["गणपति","विनायक","गजानन","बप्पा"],"about":"Lord of beginnings and remover of obstacles, so every puja begins with him. Son of Shiv and Parvati, he rides a mouse and loves modak.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/Ganesha_Basohli_miniature_circa_1730_Dubost_p73.jpg/330px-Ganesha_Basohli_miniature_circa_1730_Dubost_p73.jpg","page":"https://commons.wikimedia.org/wiki/File:Ganesha_Basohli_miniature_circa_1730_Dubost_p73.jpg","cap":"Ganesha, Basohli miniature, c. 1730","by":"Pahari (Basohli) painter","pos":"50% 30%"},"day":3},{"id":"vishnu","n":"Vishnu","d":"श्री विष्णु","ini":"वि","c":"#1D4E89","aka":["vishnu","narayan","narayana","hari","jagdish","jagadish","satyanarayan"],"akaD":["नारायण","हरि","जगदीश"],"about":"The preserver, who takes avatars such as Ram and Krishna whenever dharma is in danger. He rests on the serpent Shesh, with Lakshmi at his feet.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Raja_Ravi_Varma%2C_Seshanarayana_%28Oleographic_print%29.jpg/330px-Raja_Ravi_Varma%2C_Seshanarayana_%28Oleographic_print%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Raja_Ravi_Varma%2C_Seshanarayana_%28Oleographic_print%29.jpg","cap":"Seshanarayana, oleograph","by":"Raja Ravi Varma","pos":"50% 45%"},"day":4},{"id":"shiv","n":"Shiv","d":"भगवान शिव","ini":"शि","c":"#4B5B7A","aka":["shiv","shiva","mahadev","mahadeva","bholenath","bhole","shankar","shambhu","rudra","neelkanth","omkar"],"akaD":["महादेव","भोलेनाथ","शंकर","शम्भु"],"about":"The great ascetic of Kailash, destroyer of ignorance and the kindest of gods to his devotees. The Ganga flows from his hair and the crescent moon rests on his brow.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8f/A_version_from_the_Ravi_Varma_press-_%22Shankar%2C%22_c.1910%27s.jpg/330px-A_version_from_the_Ravi_Varma_press-_%22Shankar%2C%22_c.1910%27s.jpg","page":"https://commons.wikimedia.org/wiki/File:A_version_from_the_Ravi_Varma_press-_%22Shankar%2C%22_c.1910%27s.jpg","cap":"Shankar, Ravi Varma Press, c. 1910s","by":"Ravi Varma Press","pos":"50% 22%"},"day":1},{"id":"durga","n":"Durga","d":"माँ दुर्गा","ini":"दु","c":"#A3121F","aka":["durga","ambe","amba","jagdamba","mata rani","sherawali","bhavani","gauri","devi","sherowali"],"akaD":["अम्बे","जगदम्बा","शेरावाली","भवानी","माता रानी"],"about":"The Mother Goddess who rides a lion and defeated Mahishasur. Navratri, her nine nights, is one of the great festivals of the year.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Raja_Ravi_Varma%2C_Ambika_%28Oleographic_print%29.jpg/330px-Raja_Ravi_Varma%2C_Ambika_%28Oleographic_print%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Raja_Ravi_Varma%2C_Ambika_%28Oleographic_print%29.jpg","cap":"Ambika, oleograph","by":"Raja Ravi Varma","pos":"50% 25%"},"day":5},{"id":"lakshmi","n":"Lakshmi","d":"माँ लक्ष्मी","ini":"ल","c":"#B4235F","aka":["lakshmi","laxmi","mahalakshmi","kamla","kamala"],"akaD":["महालक्ष्मी","कमला"],"about":"Goddess of wealth, fortune and grace, consort of Vishnu. She is welcomed into every home with lamps on Diwali night.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/a6/Raja_Ravi_Varma%2C_Goddess_Lakshmi%2C_1896.jpg/330px-Raja_Ravi_Varma%2C_Goddess_Lakshmi%2C_1896.jpg","page":"https://commons.wikimedia.org/wiki/File:Raja_Ravi_Varma%2C_Goddess_Lakshmi%2C_1896.jpg","cap":"Goddess Lakshmi, 1896","by":"Raja Ravi Varma","pos":"50% 18%"},"day":5},{"id":"saraswati","n":"Saraswati","d":"माँ सरस्वती","ini":"स","c":"#3B6E8F","aka":["saraswati","sarasvati","sharda","sharada","vagdevi","veena vadini"],"akaD":["शारदा","वीणावादिनी","वाग्देवी"],"about":"Goddess of learning, speech and music, who holds the veena and rides a swan. Students pray to her before study, especially on Basant Panchami.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1a/Raja_Ravi_Varma%2C_Goddess_Saraswati.jpg/330px-Raja_Ravi_Varma%2C_Goddess_Saraswati.jpg","page":"https://commons.wikimedia.org/wiki/File:Raja_Ravi_Varma%2C_Goddess_Saraswati.jpg","cap":"Goddess Saraswati","by":"Raja Ravi Varma","pos":"50% 24%"}},{"id":"hanuman","n":"Hanuman","d":"श्री हनुमान","ini":"ह","c":"#D9620B","aka":["hanuman","bajrang","bajrangbali","pavanputra","pawanputra","maruti","anjaneya","sankat mochan","kesari nandan"],"akaD":["बजरंगबली","पवनपुत्र","मारुति","संकटमोचन"],"about":"Son of the wind god, devoted servant of Shri Ram, and a symbol of strength and fearlessness. He carried the mountain of herbs to save Lakshman.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Hanuman_fetches_the_herb-bearing_mountain%2C_in_a_print_from_the_Ravi_Varma_Press%2C_1910%27s.jpg/330px-Hanuman_fetches_the_herb-bearing_mountain%2C_in_a_print_from_the_Ravi_Varma_Press%2C_1910%27s.jpg","page":"https://commons.wikimedia.org/wiki/File:Hanuman_fetches_the_herb-bearing_mountain%2C_in_a_print_from_the_Ravi_Varma_Press%2C_1910%27s.jpg","cap":"Hanuman fetches the herb-bearing mountain, Ravi Varma Press, 1910s","by":"Ravi Varma Press","pos":"50% 28%"},"day":2},{"id":"ram","n":"Ram","d":"श्री राम","ini":"रा","c":"#24705F","aka":["ram","rama","raghunath","raghav","raghupati","siyaram","sitaram"],"akaD":["रघुनाथ","राघव","सियाराम"],"about":"The seventh avatar of Vishnu and the ideal king of the Ramayan, worshipped with Sita, Lakshman and Hanuman as the Ram Panchayatan.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Ramapanchayan%2C_Raja_Ravi_Varma_%28Lithograph%29.jpg/330px-Ramapanchayan%2C_Raja_Ravi_Varma_%28Lithograph%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Ramapanchayan%2C_Raja_Ravi_Varma_%28Lithograph%29.jpg","cap":"Ram Panchayatan, lithograph, before 1906","by":"Raja Ravi Varma","pos":"50% 35%"}},{"id":"krishna","n":"Krishna","d":"श्री कृष्ण","ini":"कृ","c":"#2A3A85","aka":["krishna","krishn","kanha","kanhaiya","gopal","shyam","murari","giridhar","kunj bihari","banke bihari","govind"],"akaD":["कान्हा","गोपाल","श्याम","गिरिधर","गोविन्द"],"about":"The eighth avatar of Vishnu: the butter-stealing child of Gokul, the flute player of Vrindavan, and the teacher of the Bhagavad Gita.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Raja_Ravi_Varma%2C_Sri_Krishna_as_Envoy.jpg/330px-Raja_Ravi_Varma%2C_Sri_Krishna_as_Envoy.jpg","page":"https://commons.wikimedia.org/wiki/File:Raja_Ravi_Varma%2C_Sri_Krishna_as_Envoy.jpg","cap":"Sri Krishna as Envoy, 1906","by":"Raja Ravi Varma","pos":"50% 18%"}},{"id":"surya","n":"Surya","d":"सूर्य देव","ini":"सू","c":"#C77A0A","aka":["surya","suryadev","sun","savitr","savita","aditya","bhaskar","dinkar"],"akaD":["सविता","आदित्य","भास्कर","दिनकर"],"about":"The Sun, the visible god, worshipped at sunrise with water offerings. The Gayatri mantra is addressed to him as Savitr, and Chhath is his great festival.","img":{"src":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Surya_in_his_chariot.jpg/330px-Surya_in_his_chariot.jpg","page":"https://commons.wikimedia.org/wiki/File:Surya_in_his_chariot.jpg","cap":"Surya in his chariot, late 19th century","by":"Unknown artist","pos":"50% 40%"},"day":0},{"id":"ishvar","n":"Ishvar","d":"ईश्वर","ini":"ॐ","c":"#7A5A2E","aka":["god","bhagwan","ishwar","prayer","prarthana"],"akaD":["भगवान","प्रार्थना"],"gallery":false,"label":"Universal prayers","about":"Prayers addressed to God in any form, sung by people of every tradition."}],"kinds":[{"id":"aarti","n":"Aarti","pl":"Aartis","d":"आरती","note":"Sung while the lamp is waved before the deity."},{"id":"chalisa","n":"Chalisa","pl":"Chalisas","d":"चालीसा","note":"Forty chaupais in praise of a deity, recited daily by millions."},{"id":"stotra","n":"Stotra","pl":"Stotras and stutis","d":"स्तोत्र","note":"Hymns of praise, most in Sanskrit, including ashtakams of eight verses."},{"id":"mantra","n":"Mantra","pl":"Mantras and shlokas","d":"मंत्र","note":"Short sacred verses for daily prayer, study and japa."},{"id":"bhajan","n":"Bhajan","pl":"Bhajans","d":"भजन","note":"Devotional songs of the saint-poets: Tulsidas, Surdas, Meera, Narsinh Mehta."},{"id":"granth","n":"Granth","pl":"Granths","d":"ग्रंथ","note":"Scriptures, read chapter by chapter."}],"occasions":{"ganesh-chaturthi":{"n":"Ganesh Chaturthi","d":"गणेश चतुर्थी","aka":["ganeshotsav","ganesh utsav","vinayaka chaturthi"],"note":"Ten days of Ganeshotsav. In Maharashtra every aarti session opens with Sukhkarta Dukhharta."},"navratri":{"n":"Navratri","d":"नवरात्रि","aka":["navaratri","navratra","durga puja"],"note":"Nine nights of the Goddess. Jai Ambe Gauri is sung every morning and evening."},"dussehra":{"n":"Dussehra","d":"दशहरा","aka":["dasara","dasehra","vijayadashami"],"note":"Ram’s victory over Ravan, the day after Navratri ends."},"dhanteras":{"n":"Dhanteras","d":"धनतेरस","aka":["dhantrayodashi"],"note":"Lamps are lit at dusk and Lakshmi is worshipped for the coming year."},"diwali":{"n":"Diwali","d":"दीपावली","aka":["deepavali","divali","lakshmi puja"],"note":"Lakshmi Puja at dusk. Most homes begin with the Ganesh aarti, then Lakshmi."},"govardhan":{"n":"Govardhan Puja","d":"गोवर्धन पूजा","aka":["annakut"],"note":"Offerings to Krishna as Giridhar, who lifted Govardhan hill."},"mahashivratri":{"n":"Maha Shivratri","d":"महाशिवरात्रि","aka":["shivratri","shivaratri"],"note":"Night-long worship of Shiv."},"shravan":{"n":"Sawan month","d":"सावन","aka":["shravan","savan","sawan somvar"],"note":"Shiv’s month; Mondays are kept with special devotion."},"janmashtami":{"n":"Janmashtami","d":"जन्माष्टमी","aka":["krishna janmashtami","gokulashtami"],"note":"Krishna’s birth, celebrated at midnight."},"holi":{"n":"Holi","d":"होली","aka":[],"note":"The festival of colours, dear to Krishna’s Braj."},"ram-navami":{"n":"Ram Navami","d":"राम नवमी","aka":[],"note":"The birth of Shri Ram."},"hanuman-jayanti":{"n":"Hanuman Jayanti","d":"हनुमान जयंती","aka":["hanuman janmotsav"],"note":"Hanuman’s birth, on Chaitra Purnima in North India."},"satyanarayan":{"n":"Satyanarayan Katha","d":"सत्यनारायण कथा","aka":["satyanarayan puja"],"note":"Om Jai Jagdish Hare is the aarti of the katha."},"griha-pravesh":{"n":"Griha Pravesh","d":"गृह प्रवेश","aka":["housewarming"],"note":"Moving into a new home."},"sundarkand":{"n":"Sundarkand path","d":"सुंदरकांड पाठ","aka":["sunderkand","ramayan path"],"note":"Recitation of the Sundarkand, usually closed with Hanuman’s aarti."},"daily":{"n":"Daily aarti","d":"नित्य आरती","aka":["daily","sandhya","evening","morning"],"note":"Sung any day, morning or evening."},"closing":{"n":"Close of any aarti","d":"आरती के अंत में","aka":["closing","end"],"note":"Recited as the flame is offered at the end."},"basant-panchami":{"n":"Basant Panchami","d":"बसंत पंचमी","aka":["vasant panchami","saraswati puja"],"note":"Saraswati Puja at the start of spring. Students place their books before the goddess."},"chhath":{"n":"Chhath Puja","d":"छठ पूजा","aka":["chhath","chhathi maiya","surya shashthi"],"note":"Offerings to the setting and rising Sun, kept with great devotion in Bihar and eastern Uttar Pradesh."},"gita-jayanti":{"n":"Gita Jayanti","d":"गीता जयंती","aka":["mokshada ekadashi"],"note":"The day Krishna taught the Gita to Arjun, on Margashirsha Shukla Ekadashi."},"morning":{"n":"Morning prayer","d":"प्रातः प्रार्थना","aka":["morning","prabhat","subah"],"note":"Short prayers for the start of the day or before study."},"meals":{"n":"Before meals","d":"भोजन से पहले","aka":["bhojan mantra","food"],"note":"Recited before eating, offering the food first."}},"occOrder":["daily","morning","closing","navratri","dussehra","dhanteras","diwali","govardhan","chhath","ganesh-chaturthi","basant-panchami","mahashivratri","shravan","janmashtami","holi","ram-navami","hanuman-jayanti","gita-jayanti","satyanarayan","sundarkand","griha-pravesh","meals"],"weekdays":[{"n":"Sunday","d":"रविवार","who":"Surya Dev","ids":["gayatri-mantra","om-jai-jagdish-hare"],"note":"Many offer water to the rising sun and recite the Gayatri mantra."},{"n":"Monday","d":"सोमवार","who":"Shiv ji","ids":["om-jai-shiv-omkara","shiv-rudrashtakam","karpur-gauram","mahamrityunjaya-mantra"]},{"n":"Tuesday","d":"मंगलवार","who":"Hanuman ji","ids":["hanuman-chalisa","aarti-keejai-hanuman-lala-ki","shri-ramchandra-kripalu"],"note":"Many homes also worship Durga on Tuesdays."},{"n":"Wednesday","d":"बुधवार","who":"Ganesh ji","ids":["jai-ganesh-deva","sukhkarta-dukhharta","vakratunda-mahakaya"]},{"n":"Thursday","d":"गुरुवार","who":"Vishnu ji","ids":["om-jai-jagdish-hare","vaishnav-jan-to"]},{"n":"Friday","d":"शुक्रवार","who":"Lakshmi Mata","ids":["om-jai-lakshmi-mata","jai-ambe-gauri"],"note":"Durga and Santoshi Mata are also worshipped on Fridays."},{"n":"Saturday","d":"शनिवार","who":"Shani Dev and Hanuman ji","ids":["hanuman-chalisa","aarti-keejai-hanuman-lala-ki"],"note":"There’s no Shani aarti in the collection yet."}],"fests":[{"date":"2026-10-11","len":9,"occ":"navratri","label":"Sharad Navratri"},{"date":"2026-10-20","occ":"dussehra"},{"date":"2026-11-06","occ":"dhanteras"},{"date":"2026-11-08","occ":"diwali","label":"Diwali · Lakshmi Puja"},{"date":"2026-11-15","occ":"chhath","label":"Chhath Puja, evening arghya"}],"presets":[{"n":"Daily evening aarti","ids":["jai-ganesh-deva","om-jai-jagdish-hare","karpur-gauram"]},{"n":"Morning prayers","ids":["gayatri-mantra","vakratunda-mahakaya","saraswati-vandana","tvameva-mata"]},{"n":"Diwali Lakshmi Puja","ids":["jai-ganesh-deva","om-jai-lakshmi-mata","om-jai-jagdish-hare","karpur-gauram"]},{"n":"Navratri","ids":["jai-ganesh-deva","jai-ambe-gauri","karpur-gauram"]},{"n":"Monday, for Shiv ji","ids":["jai-ganesh-deva","shiv-rudrashtakam","om-jai-shiv-omkara","karpur-gauram"]},{"n":"Tuesday, for Hanuman ji","ids":["hanuman-chalisa","aarti-keejai-hanuman-lala-ki","shri-ramchandra-kripalu"]}],"texts":[{"id":"aarti-keejai-hanuman-lala-ki","kind":"aarti","deity":"hanuman","lang":"hi","language":"Hindi","region":"North India","title":{"d":"आरती कीजै हनुमान लला की","r":"Aarti Keejai Hanuman Lala Ki","en":"Aarti of Shri Hanuman"},"auth":{"t":"Traditional. Some versions close with a line naming Tulsidas.","c":"traditional"},"occ":["hanuman-jayanti","sundarkand","daily"],"when":"Sung on Tuesdays and Saturdays, on Hanuman Jayanti, and after Hanuman Chalisa or a Sundarkand path.","dialect":"Awadhi","notes":"The order of the couplets varies between editions.","refrain":{"d":"आरती कीजै हनुमान लला की।\nदुष्ट दलन रघुनाथ कला की॥","r":"Aarti keejai Hanuman Lala ki,\nDusht dalan Raghunath kala ki.","m":"Offer the aarti to beloved Hanuman, crusher of the wicked, a living ray of Raghunath’s power."},"refrainFirst":true,"verses":[{"d":"जाके बल से गिरिवर काँपे।\nरोग दोष जाके निकट न झाँके॥","r":"Jake bal se girivar kaanpe,\nRog dosh jake nikat na jhaanke.","m":"At his strength even great mountains tremble; disease and misfortune dare not come near him."},{"d":"अंजनि पुत्र महा बलदायी।\nसन्तन के प्रभु सदा सहाई॥","r":"Anjani putra maha baldayi,\nSantan ke prabhu sada sahai.","m":"Son of Anjani, giver of great strength, the lord who always helps the good."},{"d":"दे बीरा रघुनाथ पठाए।\nलंका जारि सिया सुधि लाए॥","r":"De beera Raghunath pathaye,\nLanka jaari Siya sudhi laye.","m":"Raghunath handed him the betel-leaf token and sent him forth; he burned Lanka and brought back news of Sita."},{"d":"लंका सो कोट समुद्र सी खाई।\nजात पवनसुत बार न लाई॥","r":"Lanka so kot samudra si khai,\nJaat Pavansut baar na lai.","m":"Lanka was a fortress with the ocean for a moat, yet the son of the Wind crossed it without a moment’s delay."},{"d":"लंका जारि असुर संहारे।\nसियारामजी के काज सँवारे॥","r":"Lanka jaari asur sanhaare,\nSiyaramji ke kaaj sanvaare.","m":"He set Lanka ablaze, destroyed the demons and accomplished the work of Sita and Ram."},{"d":"लक्ष्मण मूर्छित पड़े सकारे।\nआनि संजीवन प्राण उबारे॥","r":"Lakshman moorchhit pade sakare,\nAani sanjivan praan ubaare.","m":"When Lakshman lay unconscious, he brought the life-giving herb by dawn and saved his life."},{"d":"पैठि पाताल तोरि जम कारे।\nअहिरावण की भुजा उखारे॥","r":"Paithi patal tori jam kaare,\nAhiravan ki bhuja ukhaare.","m":"He entered the netherworld, broke through its deadly defences and tore off Ahiravan’s arms."},{"d":"बाएँ भुजा असुर दल मारे।\nदाहिने भुजा सन्तजन तारे॥","r":"Baayen bhuja asur dal maare,\nDahine bhuja santjan taare.","m":"With his left arm he struck down the demon armies; with his right he rescued the good."},{"d":"सुर नर मुनि आरती उतारें।\nजय जय जय हनुमान उचारें॥","r":"Sur nar muni aarti utaaren,\nJai jai jai Hanuman uchaaren.","m":"Gods, humans and sages wave the aarti to him, calling out “Victory, victory, victory to Hanuman!”"},{"d":"कंचन थार कपूर लौ छाई।\nआरती करत अंजना माई॥","r":"Kanchan thaar kapoor lau chhai,\nAarti karat Anjana maai.","m":"With the camphor flame glowing on a golden plate, Mother Anjana herself performs his aarti."},{"d":"जो हनुमानजी की आरती गावे।\nबसि बैकुण्ठ परमपद पावे॥","r":"Jo Hanumanji ki aarti gaave,\nBasi Baikunth parampad paave.","m":"Whoever sings Hanuman’s aarti dwells in Vaikunth and attains the highest state."}]},{"id":"aarti-kunj-bihari-ki","kind":"aarti","deity":"krishna","lang":"hi","language":"Hindi","region":"North India, especially Braj","title":{"d":"आरती कुंजबिहारी की","r":"Aarti Kunj Bihari Ki","en":"Aarti of Shri Krishna"},"auth":{"t":"Traditional","c":"traditional"},"occ":["janmashtami","govardhan","holi","daily"],"when":"The best-known Krishna aarti, sung on Janmashtami, at Braj festivals and in daily worship. “Giridhar” recalls Krishna lifting Govardhan hill, so it is also sung on Govardhan Puja.","dialect":"Braj Bhasha","notes":"Each stanza runs straight into “श्री गिरिधर कृष्णमुरारी की”. Wording varies, for example “टेर सुन दीन दुखारी की” or “दीन भिखारी की”.","refrain":{"d":"आरती कुंजबिहारी की,\nश्री गिरिधर कृष्णमुरारी की॥","r":"Aarti Kunj Bihari ki,\nShri Giridhar Krishna Murari ki.","m":"The aarti of Kunj Bihari, who roams the groves of Vrindavan: of Shri Giridhar, Krishna, Murari."},"refrainFirst":true,"verses":[{"d":"गले में बैजंती माला, बजावै मुरली मधुर बाला।\nश्रवण में कुण्डल झलकाला, नंद के आनंद नंदलाला।\nगगन सम अंग कांति काली, राधिका चमक रही आली।\nलतन में ठाढ़े बनमाली; भ्रमर सी अलक, कस्तूरी तिलक,\nचंद्र सी झलक; ललित छवि श्यामा प्यारी की॥","r":"Gale mein Baijanti mala, bajavai murli madhur bala,\nShravan mein kundal jhalkala, Nand ke anand Nandlala.\nGagan sam ang kanti kali, Radhika chamak rahi aali,\nLatan mein thaadhe Banmali; bhramar si alak, kasturi tilak,\nChandra si jhalak; lalit chhavi Shyama pyari ki.","m":"He wears the Vaijayanti garland and plays his flute sweetly; earrings glitter in his ears, Nandlal, the joy of Nand. His body is dark as the sky and Radha shines beside him; he stands among the creepers with curls like black bees, a musk tilak and a moon-like glow — the lovely beauty of Shyama’s beloved."},{"d":"कनकमय मोर मुकुट बिलसै, देवता दरसन को तरसैं।\nगगन सों सुमन रासि बरसै;\nबजे मुरचंग, मधुर मिरदंग, ग्वालिन संग;\nअतुल रति गोप कुमारी की॥","r":"Kanakmay mor mukut bilsai, devta darsan ko tarsain,\nGagan son suman raasi barsai;\nBaje murchang, madhur mirdang, gwalin sang;\nAtul rati gop kumari ki.","m":"A golden peacock-feather crown gleams; the gods long for a glimpse of him and flowers rain from the sky. The murchang and mridang play sweetly among the cowherd girls, whose love for him has no equal."},{"d":"जहां ते प्रकट भई गंगा, कलुष कलि हारिणि श्रीगंगा।\nस्मरन ते होत मोह भंगा;\nबसी शिव सीस, जटा के बीच, हरै अघ कीच;\nचरन छवि श्रीबनवारी की॥","r":"Jahan te pragat bhai Ganga, kalush kali harini Shri Ganga,\nSmaran te hot moh bhanga;\nBasi Shiv sees, jata ke beech, harai agh keech;\nCharan chhavi Shri Banwari ki.","m":"The beauty of Banwari’s feet, from which the Ganga flowed: Shri Ganga, who washes away the impurity of this age, whose remembrance breaks delusion, who lives in Shiv’s matted hair and cleanses the mire of sin."},{"d":"चमकती उज्ज्वल तट रेनू, बज रही वृंदावन बेनू।\nचहुं दिसि गोपि ग्वाल धेनू;\nहंसत मृदु मंद, चांदनी चंद, कटत भव फंद;\nटेर सुन दीन दुखारी की॥","r":"Chamakti ujjwal tat renu, baj rahi Vrindavan benu,\nChahun disi gopi gwal dhenu;\nHansat mridu mand, chandni chand, katat bhav phand;\nTer sun deen dukhari ki.","m":"The bright sand of the riverbank glitters and the flute sounds through Vrindavan, with gopis, cowherds and cows all around. He smiles softly, like moonlight, cutting the bonds of worldly life, and hears the call of the humble and suffering."}]},{"id":"jai-ambe-gauri","kind":"aarti","deity":"durga","lang":"hi","language":"Hindi","region":"North and West India","title":{"d":"जय अम्बे गौरी","r":"Jai Ambe Gauri","en":"Aarti of Maa Durga"},"auth":{"t":"Traditional. The closing verse names Swami Shivanand.","c":"attributed"},"occ":["navratri","dussehra","daily"],"when":"The central aarti of Navratri across North India, sung morning and evening through the nine nights, and on Tuesdays and Fridays.","notes":"Wording varies between editions: “हरि ब्रह्मा शिवरी” or “शिवजी” in the refrain, and the four-arms line appears with either “वरमुद्रा धारी” or “खड्ग खप्पर धारी”.","refrain":{"d":"जय अम्बे गौरी, मैया जय श्यामा गौरी।\nतुमको निशदिन ध्यावत, हरि ब्रह्मा शिवरी॥","r":"Jai Ambe Gauri, Maiya jai Shyama Gauri,\nTumko nishdin dhyavat, Hari Brahma Shivri.","m":"Glory to Mother Ambe, to Gauri, to Shyama! Vishnu, Brahma and Shiv meditate on you day and night."},"refrainFirst":true,"verses":[{"d":"माँग सिन्दूर विराजत, टीको मृगमद को।\nउज्ज्वल से दोउ नैना, चन्द्रवदन नीको॥","r":"Maang sindoor virajat, teeko mrigmad ko,\nUjjwal se dou naina, chandravadan neeko.","m":"Vermilion graces the parting of your hair, with a tilak of musk; your eyes are bright and your face is lovely as the moon."},{"d":"कनक समान कलेवर, रक्ताम्बर राजै।\nरक्तपुष्प गल माला, कण्ठन पर साजै॥","r":"Kanak samaan kalevar, raktambar raajai,\nRaktapushp gal mala, kanthan par saajai.","m":"Your form shines like gold, dressed in red, and a garland of red flowers adorns your neck."},{"d":"केहरि वाहन राजत, खड्ग खप्पर धारी।\nसुर नर मुनि जन सेवत, तिनके दुखहारी॥","r":"Kehari vahan raajat, khadg khappar dhari,\nSur nar muni jan sevat, tinke dukhhari.","m":"You ride the lion, holding sword and skull-bowl. Gods, humans and sages serve you, and you take away their sorrows."},{"d":"कानन कुण्डल शोभित, नासाग्रे मोती।\nकोटिक चन्द्र दिवाकर, सम राजत ज्योती॥","r":"Kaanan kundal shobhit, nasagre moti,\nKotik chandra divakar, sam raajat jyoti.","m":"Earrings shine in your ears and a pearl at your nose; your radiance equals millions of moons and suns."},{"d":"शुम्भ निशुम्भ बिदारे, महिषासुर घाती।\nधूम्र विलोचन नैना, निशदिन मदमाती॥","r":"Shumbh Nishumbh bidaare, Mahishasur ghaati,\nDhoomra vilochan naina, nishdin madmaati.","m":"You tore apart Shumbh and Nishumbh and slew Mahishasur; you struck down Dhumralochan, your eyes ablaze with divine fervour day and night."},{"d":"चण्ड मुण्ड संहारे, शोणित बीज हरे।\nमधु कैटभ दोउ मारे, सुर भयहीन करे॥","r":"Chand Mund sanhaare, shonit beej hare,\nMadhu Kaitabh dou maare, sur bhayheen kare.","m":"You destroyed Chand and Mund and vanquished Raktabeej; you slew Madhu and Kaitabh and freed the gods from fear."},{"d":"ब्रह्माणी रुद्राणी, तुम कमला रानी।\nआगम निगम बखानी, तुम शिव पटरानी॥","r":"Brahmani Rudrani, tum Kamla Rani,\nAagam nigam bakhani, tum Shiv patrani.","m":"You are Brahmani and Rudrani, and Queen Kamala; the scriptures sing your praise, chief queen of Shiv."},{"d":"चौंसठ योगिनी मंगल गावत, नृत्य करत भैरों।\nबाजत ताल मृदंगा, अरु बाजत डमरू॥","r":"Chaunsath yogini mangal gaavat, nritya karat Bhairon,\nBaajat taal mridanga, aru baajat damru.","m":"The sixty-four yoginis sing auspicious songs and Bhairav dances; cymbals and drums resound, and the damru too."},{"d":"तुम ही जग की माता, तुम ही हो भरता।\nभक्तन की दुख हरता, सुख सम्पति करता॥","r":"Tum hi jag ki mata, tum hi ho bharta,\nBhaktan ki dukh harta, sukh sampati karta.","m":"You alone are the mother of the world and its sustainer; you remove your devotees’ sorrows and bring them happiness and plenty."},{"d":"भुजा चार अति शोभित, वरमुद्रा धारी।\nमनवांछित फल पावत, सेवत नर नारी॥","r":"Bhuja chaar ati shobhit, varmudra dhari,\nManvanchhit phal paavat, sevat nar nari.","m":"Your four arms are radiant, one raised in blessing; the men and women who serve you receive what their hearts desire."},{"d":"कंचन थाल विराजत, अगर कपूर बाती।\nश्रीमालकेतु में राजत, कोटि रतन ज्योती॥","r":"Kanchan thaal virajat, agar kapoor baati,\nShrimalketu mein raajat, koti ratan jyoti.","m":"A golden plate is set with aloe-wood, camphor and wicks, and the flames shine like countless jewels."},{"d":"श्री अम्बेजी की आरती, जो कोई नर गावे।\nकहत शिवानन्द स्वामी, सुख सम्पत्ति पावे॥","r":"Shri Ambeji ki aarti, jo koi nar gaave,\nKahat Shivanand Swami, sukh sampatti paave.","m":"Whoever sings this aarti of Mother Ambe, says Swami Shivanand, gains happiness and prosperity."}]},{"id":"jai-ganesh-deva","kind":"aarti","deity":"ganesh","lang":"hi","language":"Hindi","region":"North India","title":{"d":"जय गणेश जय गणेश देवा","r":"Jai Ganesh Jai Ganesh Deva","en":"Aarti of Shri Ganesh"},"auth":{"t":"Traditional. The last verse names “Soor”, often read as Surdas.","c":"attributed"},"occ":["ganesh-chaturthi","diwali","satyanarayan","griha-pravesh","daily"],"when":"Sung first in most North Indian pujas, because Ganesh is worshipped before any other deity. Wednesday is his day.","notes":"Editions differ slightly, for example “माथे सिन्दूर सोहे” or “माथे पर तिलक सोहे”. Many families add the verse “दीनन की लाज रखो, शम्भु सुतकारी”.","refrain":{"d":"जय गणेश जय गणेश, जय गणेश देवा।\nमाता जाकी पार्वती, पिता महादेवा॥","r":"Jai Ganesh jai Ganesh, jai Ganesh Deva,\nMata jaki Parvati, pita Mahadeva.","m":"Glory to Lord Ganesh, whose mother is Parvati and whose father is Mahadev."},"refrainFirst":true,"verses":[{"d":"एक दन्त दयावन्त, चार भुजा धारी।\nमाथे सिन्दूर सोहे, मूसे की सवारी॥","r":"Ek dant dayavant, chaar bhuja dhari,\nMathe sindoor sohe, moose ki savari.","m":"The one-tusked, compassionate lord with four arms. Vermilion graces his forehead and he rides a mouse."},{"d":"पान चढ़े फूल चढ़े, और चढ़े मेवा।\nलड्डुअन का भोग लगे, सन्त करें सेवा॥","r":"Paan chadhe phool chadhe, aur chadhe meva,\nLadduan ka bhog lage, sant karen seva.","m":"Betel leaves, flowers and dry fruits are offered to him; laddus are his bhog, and the saintly serve him."},{"d":"अंधन को आँख देत, कोढ़िन को काया।\nबाँझन को पुत्र देत, निर्धन को माया॥","r":"Andhan ko aankh det, kodhin ko kaya,\nBaanjhan ko putra det, nirdhan ko maya.","m":"He gives sight to the blind, a healthy body to the afflicted, children to the childless and wealth to the poor."},{"d":"‘सूर’ श्याम शरण आए, सफल कीजे सेवा।\nमाता जाकी पार्वती, पिता महादेवा॥","r":"Soor Shyam sharan aaye, saphal keeje seva,\nMata jaki Parvati, pita Mahadeva.","m":"Soor, devotee of Shyam, has come to your refuge: make this worship fruitful, son of Parvati and Mahadev."}]},{"id":"om-jai-jagdish-hare","kind":"aarti","deity":"vishnu","lang":"hi","language":"Hindi","region":"North India, now sung everywhere","title":{"d":"ॐ जय जगदीश हरे","r":"Om Jai Jagdish Hare","en":"Aarti of Shri Vishnu"},"auth":{"t":"Pandit Shardha Ram Phillauri, around 1870","c":"known"},"occ":["daily","satyanarayan","diwali","griha-pravesh"],"when":"Probably the most widely sung aarti of all. Many homes close every evening aarti with it, whichever deity was worshipped, and it is the aarti of Satyanarayan Katha. Thursday is Vishnu’s day.","notes":"The line “श्रद्धा भक्ति बढ़ाओ” is often read as the poet’s signature, since his name was Shardha Ram. Editions differ in places, for example “मैं मूरख फलगामी” or “मैं मूरख खल कामी”.","refrain":{"d":"ॐ जय जगदीश हरे, स्वामी जय जगदीश हरे।\nभक्त जनों के संकट, दास जनों के संकट, क्षण में दूर करे॥","r":"Om jai Jagdish hare, Swami jai Jagdish hare,\nBhakt janon ke sankat, daas janon ke sankat, kshan mein door kare.","m":"Om, glory to you, Hari, Lord of the universe! You remove the troubles of your devotees and servants in an instant."},"refrainFirst":true,"verses":[{"d":"जो ध्यावे फल पावे, दुःख बिनसे मन का, स्वामी दुःख बिनसे मन का।\nसुख सम्पत्ति घर आवे, कष्ट मिटे तन का॥","r":"Jo dhyave phal pave, dukh binse man ka, Swami dukh binse man ka,\nSukh sampatti ghar aave, kasht mite tan ka.","m":"Whoever meditates on you receives the fruit, and the mind’s sorrow is destroyed; happiness and prosperity come home and the body’s suffering ends."},{"d":"मात पिता तुम मेरे, शरण गहूँ मैं किसकी, स्वामी शरण गहूँ मैं किसकी।\nतुम बिन और न दूजा, आस करूँ मैं जिसकी॥","r":"Maat pita tum mere, sharan gahoon main kiski, Swami sharan gahoon main kiski,\nTum bin aur na dooja, aas karoon main jiski.","m":"You are my mother and father; whose refuge should I seek? Without you there is no other in whom I can place my hope."},{"d":"तुम पूरण परमात्मा, तुम अन्तर्यामी, स्वामी तुम अन्तर्यामी।\nपारब्रह्म परमेश्वर, तुम सब के स्वामी॥","r":"Tum pooran Paramatma, tum Antaryami, Swami tum Antaryami,\nParabrahm Parameshwar, tum sab ke swami.","m":"You are the complete Supreme Soul, the knower of every heart: the Supreme Brahman, the Supreme Lord, master of all."},{"d":"तुम करुणा के सागर, तुम पालनकर्ता, स्वामी तुम पालनकर्ता।\nमैं मूरख फलगामी, मैं सेवक तुम स्वामी, कृपा करो भर्ता॥","r":"Tum karuna ke sagar, tum palankarta, Swami tum palankarta,\nMain moorakh phalgami, main sevak tum swami, kripa karo bharta.","m":"You are an ocean of compassion and the sustainer of all. I am foolish and chase rewards; I am your servant and you my master. Be gracious, Lord."},{"d":"तुम हो एक अगोचर, सबके प्राणपति, स्वामी सबके प्राणपति।\nकिस विधि मिलूँ दयामय, तुमको मैं कुमति॥","r":"Tum ho ek agochar, sabke pranpati, Swami sabke pranpati,\nKis vidhi miloon dayamay, tumko main kumati.","m":"You are the One beyond the senses, lord of every life. How can someone of my poor understanding reach you, merciful one?"},{"d":"दीनबन्धु दुःखहर्ता, ठाकुर तुम मेरे, स्वामी रक्षक तुम मेरे।\nअपने हाथ उठाओ, अपनी शरण लगाओ, द्वार पड़ा तेरे॥","r":"Deenbandhu dukhharta, Thakur tum mere, Swami rakshak tum mere,\nApne haath uthao, apni sharan lagao, dwaar pada tere.","m":"Friend of the humble, remover of sorrow, you are my lord and protector. Raise your hand and take me into your refuge; I lie at your door."},{"d":"विषय विकार मिटाओ, पाप हरो देवा, स्वामी पाप हरो देवा।\nश्रद्धा भक्ति बढ़ाओ, सन्तन की सेवा॥","r":"Vishay vikaar mitao, paap haro Deva, Swami paap haro Deva,\nShraddha bhakti badhao, santan ki seva.","m":"Wipe away my cravings and failings and take away my sins, Lord. Increase my faith, my devotion and my service to the saintly."},{"d":"तन मन धन सब कुछ है तेरा, स्वामी सब कुछ है तेरा।\nतेरा तुझको अर्पण, क्या लागे मेरा॥","r":"Tan man dhan sab kuchh hai tera, Swami sab kuchh hai tera,\nTera tujhko arpan, kya laage mera.","m":"Body, mind and wealth all belong to you. I offer you what is already yours; what part of it is mine?"}]},{"id":"om-jai-lakshmi-mata","kind":"aarti","deity":"lakshmi","lang":"hi","language":"Hindi","region":"North India","title":{"d":"ॐ जय लक्ष्मी माता","r":"Om Jai Lakshmi Mata","en":"Aarti of Maa Lakshmi"},"auth":{"t":"Traditional","c":"traditional"},"occ":["diwali","dhanteras","daily"],"when":"The heart of Lakshmi Puja on Diwali evening, sung after the Ganesh aarti. Also sung on Fridays and on Dhanteras.","notes":"Sung to the same tune as Om Jai Jagdish Hare, whose pattern it follows. Some editions print “हरि विष्णु विधाता” in the refrain.","refrain":{"d":"ॐ जय लक्ष्मी माता, मैया जय लक्ष्मी माता।\nतुमको निशदिन सेवत, हर विष्णु विधाता॥","r":"Om jai Lakshmi Mata, Maiya jai Lakshmi Mata,\nTumko nishdin sevat, Har Vishnu Vidhata.","m":"Om, glory to Mother Lakshmi! Shiv, Vishnu and Brahma worship you day and night."},"refrainFirst":true,"verses":[{"d":"उमा रमा ब्रह्माणी, तुम ही जग माता।\nसूर्य चन्द्रमा ध्यावत, नारद ऋषि गाता॥","r":"Uma Rama Brahmani, tum hi jag mata,\nSurya Chandrama dhyavat, Narad rishi gata.","m":"You are Uma, Rama and Brahmani, mother of the world. The sun and moon meditate on you and the sage Narad sings your glory."},{"d":"दुर्गा रूप निरंजनि, सुख सम्पत्ति दाता।\nजो कोई तुमको ध्यावत, ऋद्धि सिद्धि धन पाता॥","r":"Durga roop niranjani, sukh sampatti data,\nJo koi tumko dhyavat, riddhi siddhi dhan pata.","m":"Pure one in the form of Durga, giver of happiness and plenty: whoever meditates on you gains abundance, success and wealth."},{"d":"तुम पाताल निवासिनि, तुम ही शुभदाता।\nकर्म प्रभाव प्रकाशिनि, भवनिधि की त्राता॥","r":"Tum Patal nivasini, tum hi shubhdata,\nKarm prabhav prakashini, bhavnidhi ki trata.","m":"You dwell even in the netherworld, and you alone bestow good fortune. You bring the fruits of our deeds to light and carry us across the ocean of worldly life."},{"d":"जिस घर में तुम रहतीं, सब सद्गुण आता।\nसब सम्भव हो जाता, मन नहीं घबराता॥","r":"Jis ghar mein tum rahtin, sab sadgun aata,\nSab sambhav ho jata, man nahin ghabrata.","m":"Every virtue comes to the home where you live; everything becomes possible and the mind is free of fear."},{"d":"तुम बिन यज्ञ न होते, वस्त्र न कोई पाता।\nखान पान का वैभव, सब तुमसे आता॥","r":"Tum bin yagya na hote, vastra na koi pata,\nKhaan paan ka vaibhav, sab tumse aata.","m":"Without you no sacrifice could be performed and no one would have clothing; all the richness of food and drink comes from you."},{"d":"शुभ गुण मन्दिर सुन्दर, क्षीरोदधि जाता।\nरत्न चतुर्दश तुम बिन, कोई नहीं पाता॥","r":"Shubh gun mandir sundar, Kshirodadhi jata,\nRatna chaturdash tum bin, koi nahin pata.","m":"Beautiful temple of auspicious qualities, born of the ocean of milk: without you no one obtains the fourteen treasures."},{"d":"महालक्ष्मी जी की आरती, जो कोई जन गाता।\nउर आनन्द समाता, पाप उतर जाता॥","r":"Mahalakshmi ji ki aarti, jo koi jan gata,\nUr anand samata, paap utar jata.","m":"Whoever sings this aarti of Mahalakshmi is filled with joy, and their sins fall away."}]},{"id":"om-jai-saraswati-mata","kind":"aarti","deity":"saraswati","lang":"hi","language":"Hindi","region":"North India","title":{"d":"ॐ जय सरस्वती माता","r":"Om Jai Saraswati Mata","en":"Aarti of Maa Saraswati"},"auth":{"t":"Traditional","c":"traditional"},"occ":["basant-panchami","navratri","daily"],"when":"Sung on Basant Panchami and before study in schools and homes. In South India, Saraswati Puja falls during Navratri.","notes":"Sung to the same tune as Om Jai Jagdish Hare.","refrain":{"d":"ॐ जय सरस्वती माता, मैया जय सरस्वती माता।\nसद्गुण वैभव शालिनी, त्रिभुवन विख्याता॥","r":"Om jai Saraswati Mata, Maiya jai Saraswati Mata,\nSadgun vaibhav shalini, tribhuvan vikhyata.","m":"Om, glory to Mother Saraswati! Rich in every virtue and splendour, famed in all three worlds."},"refrainFirst":true,"verses":[{"d":"चन्द्रवदनि पद्मासिनि, द्युति मंगलकारी।\nसोहे शुभ हंस सवारी, अतुल तेजधारी॥","r":"Chandravadani padmasini, dyuti mangalkari,\nSohe shubh hans savari, atul tejdhari.","m":"Moon-faced goddess seated on a lotus, your radiance brings blessings. You ride the auspicious swan and shine with matchless light."},{"d":"बाएँ कर में वीणा, दाएँ कर माला।\nशीश मुकुट मणि सोहे, गल मोतियन माला॥","r":"Baayen kar mein veena, daayen kar mala,\nSheesh mukut mani sohe, gal motiyan mala.","m":"The veena is in your left hand and a rosary in your right. A jewelled crown graces your head and a string of pearls your neck."},{"d":"देवी शरण जो आए, उनका उद्धार किया।\nपैठी मंथरा दासी, रावण संहार किया॥","r":"Devi sharan jo aaye, unka uddhar kiya,\nPaithi Manthara dasi, Ravan sanhar kiya.","m":"Goddess, you raised up all who came to your refuge. You entered the mind of the maid Manthara and so brought about Ravan’s end."},{"d":"विद्या ज्ञान प्रदायिनि, ज्ञान प्रकाश भरो।\nमोह अज्ञान और तिमिर का, जग से नाश करो॥","r":"Vidya gyan pradayini, gyan prakash bharo,\nMoh agyan aur timir ka, jag se naash karo.","m":"Giver of learning and wisdom, fill us with the light of knowledge, and drive delusion, ignorance and darkness from the world."},{"d":"धूप दीप फल मेवा, माँ स्वीकार करो।\nज्ञानचक्षु दे माता, जग निस्तार करो॥","r":"Dhoop deep phal meva, Maa sweekar karo,\nGyanchakshu de Mata, jag nistar karo.","m":"Mother, accept our incense, lamp, fruit and dry fruits. Give us the eye of wisdom and carry the world across."},{"d":"माँ सरस्वती की आरती, जो कोई जन गावे।\nहितकारी सुखकारी, ज्ञान भक्ति पावे॥","r":"Maa Saraswati ki aarti, jo koi jan gaave,\nHitkari sukhkari, gyan bhakti paave.","m":"Whoever sings this aarti of Mother Saraswati gains wisdom and devotion, which bring wellbeing and happiness."}]},{"id":"om-jai-shiv-omkara","kind":"aarti","deity":"shiv","lang":"hi","language":"Hindi","region":"North India","title":{"d":"ॐ जय शिव ओंकारा","r":"Om Jai Shiv Omkara","en":"Aarti of Lord Shiv"},"auth":{"t":"Traditional. The closing verse names Swami Shivanand.","c":"attributed"},"occ":["mahashivratri","shravan","daily"],"when":"Sung on Mondays, through the month of Sawan and on Maha Shivratri. It praises Shiv as one with Brahma and Vishnu.","notes":"One of the most variable texts. Longer versions add verses on Kailash, the Ganga and Kashi Vishwanath, and some lines differ by region, such as “त्रिपुरारी कंसारी कर माला धारी”. This is a shorter common form.","refrain":{"d":"ॐ जय शिव ओंकारा, स्वामी जय शिव ओंकारा।\nब्रह्मा विष्णु सदाशिव, अर्द्धांगी धारा॥","r":"Om jai Shiv Omkara, Swami jai Shiv Omkara,\nBrahma Vishnu Sadashiv, ardhangi dhara.","m":"Om, glory to Shiv, embodiment of Om! You are Brahma, Vishnu and Sadashiv, and you hold your consort as half of your own body."},"refrainFirst":true,"verses":[{"d":"एकानन चतुरानन पंचानन राजे।\nहंसासन गरुड़ासन वृषवाहन साजे॥","r":"Ekanan chaturanan panchanan raje,\nHansasan Garudasan vrishvahan saje.","m":"With one face, four faces and five faces you shine, seated on the swan, on Garuda, and riding the bull."},{"d":"दो भुज चार चतुर्भुज दसभुज अति सोहे।\nत्रिगुण रूप निरखते त्रिभुवन जन मोहे॥","r":"Do bhuj chaar chaturbhuj dasbhuj ati sohe,\nTrigun roop nirakhte tribhuvan jan mohe.","m":"With two, four and ten arms you are magnificent; seeing your form of the three gunas, all three worlds are enchanted."},{"d":"अक्षमाला वनमाला मुण्डमाला धारी।\nचन्दन मृगमद सोहै भाले शशिधारी॥","r":"Akshmala vanmala mundmala dhari,\nChandan mrigmad sohai bhale shashidhari.","m":"You wear rudraksha beads, a garland of forest flowers and a garland of skulls; sandalwood and musk adorn you, and the moon rests on your brow."},{"d":"श्वेताम्बर पीताम्बर बाघम्बर अंगे।\nसनकादिक गरुड़ादिक भूतादिक संगे॥","r":"Shvetambar pitambar baghambar ange,\nSanakadik Garudadik bhootadik sange.","m":"Dressed in white, in yellow silk and in tiger skin, accompanied by sages like Sanaka, by Garuda and by hosts of spirits."},{"d":"कर के मध्य कमण्डलु चक्र त्रिशूलधर्ता।\nजगकर्ता जगभर्ता जगसंहारकर्ता॥","r":"Kar ke madhya kamandalu chakra trishooldharta,\nJagkarta jagbharta jagsanharkarta.","m":"Holding the water-pot, the discus and the trident: creator, sustainer and destroyer of the world."},{"d":"ब्रह्मा विष्णु सदाशिव जानत अविवेका।\nप्रणवाक्षर के मध्ये ये तीनों एका॥","r":"Brahma Vishnu Sadashiv janat aviveka,\nPranavakshar ke madhye ye teenon eka.","m":"Only the unwise think Brahma, Vishnu and Sadashiv are separate; within the sacred syllable Om, the three are one."},{"d":"त्रिगुणस्वामी जी की आरती जो कोई नर गावे।\nकहत शिवानन्द स्वामी मनवांछित फल पावे॥","r":"Trigunswami ji ki aarti jo koi nar gave,\nKahat Shivanand Swami manvanchhit phal pave.","m":"Whoever sings this aarti of the lord of the three gunas, says Swami Shivanand, gains the fruit of their heart’s desire."}]},{"id":"sukhkarta-dukhharta","kind":"aarti","deity":"ganesh","lang":"mr","language":"Marathi","region":"Maharashtra","title":{"d":"सुखकर्ता दुःखहर्ता","r":"Sukhkarta Dukhharta","en":"Marathi aarti of Shri Ganesh"},"auth":{"t":"Samarth Ramdas, 17th century. The last verse carries his signature, “दास रामाचा”.","c":"attributed"},"occ":["ganesh-chaturthi","daily"],"when":"Opens the aarti in Maharashtrian homes and Ganeshotsav pandals; the session usually ends with “घालीन लोटांगण” and Mantrapushpanjali.","notes":"The refrain follows each verse rather than opening the aarti. It is set in a Marathi cut of the typeface, because a few letters are traditionally drawn differently in Marathi.","refrain":{"d":"जय देव जय देव जय मंगलमूर्ती।\nदर्शनमात्रे मनकामना पुरती॥","r":"Jai Dev jai Dev jai Mangalmurti,\nDarshanmatre mankamana purti.","m":"Glory, Lord, to the auspicious one: the mere sight of you fulfils the heart’s wishes."},"refrainFirst":false,"verses":[{"d":"सुखकर्ता दुःखहर्ता वार्ता विघ्नाची।\nनुरवी पुरवी प्रेम कृपा जयाची।\nसर्वांगी सुंदर उटी शेंदुराची।\nकंठी झळके माळ मुक्ताफळांची॥","r":"Sukhkarta dukhharta varta vighnachi,\nNuravi puravi prem krupa jayachi.\nSarvangi sundar uti shendurachi,\nKanthi jhalake maal muktaphalanchi.","m":"Giver of joy and remover of sorrow, whose grace leaves not even a whisper of obstacles and showers love. His whole body glows with vermilion paste and a string of pearls gleams at his throat."},{"d":"रत्नखचित फरा तुज गौरीकुमरा।\nचंदनाची उटी कुंकुमकेशरा।\nहिरेजडित मुकुट शोभतो बरा।\nरुणझुणती नूपुरे चरणी घागरिया॥","r":"Ratnakhachit phara tuj Gaurikumara,\nChandanachi uti kumkumkeshara.\nHirejadit mukut shobhato bara,\nRunjhunati nupure charani ghagariya.","m":"Son of Gauri, jewels adorn you and you are anointed with sandalwood, kumkum and saffron. A diamond-studded crown shines on you, and anklets with tiny bells jingle at your feet."},{"d":"लंबोदर पीतांबर फणिवरबंधना।\nसरळ सोंड वक्रतुंड त्रिनयना।\nदास रामाचा वाट पाहे सदना।\nसंकटी पावावे निर्वाणी रक्षावे सुरवरवंदना॥","r":"Lambodar pitambar phanivarbandhana,\nSaral sond vakratunda trinayana.\nDas Ramacha vaat pahe sadana,\nSankati pavave nirvani rakshave survaravandana.","m":"Big-bellied lord in yellow silk with a serpent for a sash, straight-trunked, curve-faced, three-eyed. Ramdas, your servant, waits for you at home: come to us in trouble and protect us at the last, lord worshipped by the gods."}]},{"id":"maiya-mori-main-nahin-makhan-khayo","kind":"bhajan","deity":"krishna","lang":"hi","language":"Hindi","region":"All of North India, especially Braj","title":{"d":"मैया मोरी मैं नहिं माखन खायो","r":"Maiya Mori Main Nahin Makhan Khayo","en":"Little Krishna pleads his innocence"},"auth":{"t":"Surdas, 16th century. The last verse carries his name.","c":"attributed"},"occ":["janmashtami","daily"],"when":"A favourite on Janmashtami and in tellings of Krishna’s childhood, often sung to children.","dialect":"Braj Bhasha","refrain":{"d":"मैया मोरी मैं नहिं माखन खायो॥","r":"Maiya mori main nahin makhan khayo.","m":"Mother, I did not eat the butter!"},"refrainFirst":true,"verses":[{"d":"भोर भयो गैयन के पाछे, मधुबन मोहिं पठायो।\nचार पहर बंसीबट भटक्यो, साँझ परे घर आयो॥","r":"Bhor bhayo gaiyan ke pachhe, Madhuban mohin pathayo,\nChar pahar Bansibat bhatakyo, saanjh pare ghar aayo.","m":"At dawn you sent me off to Madhuban behind the cows. All day I wandered by the Bansivat tree, and came home only at dusk."},{"d":"मैं बालक बहियन को छोटो, छींको किहि बिधि पायो।\nग्वाल बाल सब बैर परे हैं, बरबस मुख लपटायो॥","r":"Main balak bahiyan ko chhoto, chheenko kihi bidhi paayo,\nGwal baal sab bair pare hain, barbas mukh laptayo.","m":"I’m a little boy with short arms; how could I reach the pot hanging from the rafters? The cowherd boys are all against me. They smeared the butter on my face!"},{"d":"तू जननी मन की अति भोरी, इनके कहे पतिआयो।\nजिय तेरे कछु भेद उपजि है, जानि परायो जायो॥","r":"Tu janani man ki ati bhori, inke kahe patiayo,\nJiya tere kachhu bhed upaji hai, jaani parayo jaayo.","m":"Mother, you are far too trusting; you believed what they said. Some doubt has come into your heart, as if I were somebody else’s child."},{"d":"यह लै अपनी लकुटि कमरिया, बहुतहिं नाच नचायो।\nसूरदास तब बिहँसि जसोदा, लै उर कंठ लगायो॥","r":"Yah lai apni lakuti kamariya, bahutahin naach nachayo,\nSurdas tab bihansi Jasoda, lai ur kanth lagayo.","m":"“Here, take back your stick and blanket; you’ve made me dance enough!” Then, says Surdas, Yashoda laughed and hugged him close."}]},{"id":"payoji-maine-ram-ratan-dhan-payo","kind":"bhajan","deity":"krishna","lang":"hi","language":"Hindi","region":"All of North India","title":{"d":"पायो जी मैंने राम रतन धन पायो","r":"Payoji Maine Ram Ratan Dhan Payo","en":"Meera’s song of the priceless treasure"},"auth":{"t":"Meerabai, 16th century. The last line carries her name.","c":"attributed"},"occ":["janmashtami","daily"],"when":"One of the best-loved bhajans of Meerabai, sung at satsangs and on Janmashtami.","dialect":"Rajasthani and Braj","notes":"Meera’s Lord is Krishna, Giridhar Nagar; “Ram ratan”, the jewel of Ram’s name, is the divine name itself. Wording varies between singers.","refrain":{"d":"पायो जी मैंने राम रतन धन पायो॥","r":"Payo ji maine Ram ratan dhan payo.","m":"I have found it: the priceless jewel of the divine name."},"refrainFirst":true,"verses":[{"d":"वस्तु अमोलक दी मेरे सतगुरु, किरपा कर अपनायो॥","r":"Vastu amolak di mere Satguru, kirpa kar apnayo.","m":"My true Guru gave me something beyond price and, in his grace, made me his own."},{"d":"जनम जनम की पूँजी पाई, जग में सभी खोवायो॥","r":"Janam janam ki poonji paai, jag mein sabhi khovayo.","m":"I have found the treasure of many lifetimes, and let go of everything else in the world."},{"d":"खरचै न खूटै, चोर न लूटै, दिन दिन बढ़त सवायो॥","r":"Kharchai na khootai, chor na lootai, din din badhat savayo.","m":"Spending it does not use it up, thieves cannot steal it; it grows by a quarter every day."},{"d":"सत की नाव खेवटिया सतगुरु, भवसागर तर आयो॥","r":"Sat ki naav khevatiya Satguru, bhavsagar tar aayo.","m":"In the boat of truth, with my Guru at the oars, I have crossed the ocean of worldly life."},{"d":"मीरा के प्रभु गिरिधर नागर, हरख हरख जस गायो॥","r":"Meera ke prabhu Giridhar Nagar, harakh harakh jas gaayo.","m":"Meera’s Lord is Giridhar Nagar; overflowing with joy, she sings his praise."}]},{"id":"raghupati-raghav-raja-ram","kind":"bhajan","deity":"ram","lang":"hi","language":"Hindi","region":"All of India","title":{"d":"रघुपति राघव राजा राम","r":"Raghupati Raghav Raja Ram","en":"The Ram Dhun"},"auth":{"t":"Traditional Ram Dhun. The version with “ईश्वर अल्लाह तेरो नाम” was sung at Mahatma Gandhi’s prayer meetings.","c":"traditional"},"occ":["ram-navami","daily"],"when":"Sung in kirtan, at prayer meetings and school assemblies, and on 2 October.","form":"Dhun","notes":"Gandhi’s version was sung on the Salt March of 1930. Older devotional forms repeat only the names of Sita and Ram.","refrain":{"d":"रघुपति राघव राजाराम, पतित पावन सीताराम॥","r":"Raghupati Raghav Raja Ram, patit pavan Sitaram.","m":"Lord of the Raghus, King Ram, with Sita: purifier of the fallen."},"refrainFirst":true,"verses":[{"d":"सीताराम सीताराम, भज प्यारे तू सीताराम॥","r":"Sitaram Sitaram, bhaj pyare tu Sitaram.","m":"Sita-Ram, Sita-Ram: dear one, sing the names of Sita and Ram."},{"d":"ईश्वर अल्लाह तेरो नाम, सब को सन्मति दे भगवान॥","r":"Ishwar Allah tero naam, sab ko sanmati de Bhagwan.","m":"Ishwar and Allah are both your names. Lord, give everyone wisdom and goodwill."}]},{"id":"thumak-chalat-ramchandra","kind":"bhajan","deity":"ram","lang":"hi","language":"Hindi","region":"All of North India","title":{"d":"ठुमक चलत रामचंद्र","r":"Thumak Chalat Ramchandra","en":"Baby Ram takes his first steps"},"auth":{"t":"Goswami Tulsidas, from the Gitavali","c":"attributed"},"occ":["ram-navami","daily"],"when":"Sung on Ram Navami and in Ram bhajans, picturing Ram as a toddler in Ayodhya.","dialect":"Braj Bhasha","refrain":{"d":"ठुमक चलत रामचंद्र बाजत पैंजनियाँ॥","r":"Thumak chalat Ramchandra baajat painjaniyan.","m":"Little Ramchandra toddles along, his anklets jingling."},"refrainFirst":true,"verses":[{"d":"किलकि किलकि उठत धाय गिरत भूमि लटपटाय।\nधाय मात गोद लेत दशरथ की रनियाँ॥","r":"Kilaki kilaki uthat dhaay girat bhoomi latpataay,\nDhaay maat god let Dashrath ki raniyan.","m":"Squealing with laughter he gets up and runs, then stumbles and falls; Dasharath’s queens rush to gather him into their laps."},{"d":"अंचल रज अंग झारि विविध भाँति सो दुलारि।\nतन मन धन वारि वारि कहत मृदु बचनियाँ॥","r":"Anchal raj ang jhaari vividh bhaanti so dulaari,\nTan man dhan vaari vaari kahat mridu bachaniyan.","m":"With the ends of their saris they brush the dust from him and fuss over him in every way, giving their all to him and speaking soft words."},{"d":"विद्रुम से अरुण अधर बोलत मुख मधुर मधुर।\nसुभग नासिका में चारु लटकत लटकनियाँ॥","r":"Vidrum se arun adhar bolat mukh madhur madhur,\nSubhag nasika mein charu latkat latkaniyan.","m":"His lips are red as coral as he babbles sweetly, and a pretty ornament dangles at his nose."},{"d":"तुलसीदास अति आनंद देख के मुखारविंद।\nरघुवर छबि के समान रघुवर छबि बनियाँ॥","r":"Tulsidas ati anand dekh ke mukharavind,\nRaghuvar chhabi ke saman Raghuvar chhabi baniyan.","m":"Tulsidas is overjoyed to see that lotus face: Raghuvar’s beauty can be compared only with Raghuvar’s beauty."}]},{"id":"vaishnav-jan-to","kind":"bhajan","deity":"vishnu","lang":"gu","language":"Gujarati","region":"Gujarat, and all of India through Gandhi’s prayer meetings","title":{"d":"वैष्णव जन तो तेने कहिये","r":"Vaishnav Jan To Tene Kahiye","en":"Who is a true devotee"},"auth":{"t":"Narsinh Mehta, 15th century. The last verse carries his name.","c":"known"},"occ":["daily"],"when":"Mahatma Gandhi’s favourite bhajan, sung at his prayer meetings and today at school assemblies and on 2 October.","notes":"Shown in Devanagari, as printed in most Hindi bhajan books. In Gujarati script it begins “વૈષ્ણવ જન તો તેને કહીએ”.","refrain":{"d":"वैष्णव जन तो तेने कहिये जे पीड पराई जाणे रे।\nपर दुःखे उपकार करे तो ये मन अभिमान न आणे रे॥","r":"Vaishnav jan to tene kahiye je peed parai jaane re,\nPar dukhe upkar kare to ye man abhiman na aane re.","m":"Call that person a true devotee who feels the pain of others, who helps those in sorrow and never lets pride into the mind."},"refrainFirst":true,"verses":[{"d":"सकळ लोकमां सहुने वंदे, निंदा न करे केनी रे।\nवाच काछ मन निश्चळ राखे, धन धन जननी तेनी रे॥","r":"Sakal lokman sahune vande, ninda na kare keni re,\nVach kachh man nishchal rakhe, dhan dhan janani teni re.","m":"Such a person honours everyone in the world and speaks ill of no one, and keeps word, deed and mind steady. Blessed, blessed is the mother who bore them."},{"d":"समदृष्टि ने तृष्णा त्यागी, परस्त्री जेने मात रे।\nजिह्वा थकी असत्य न बोले, परधन नव झाले हाथ रे॥","r":"Samdrishti ne trushna tyagi, parstri jene maat re,\nJihva thaki asatya na bole, pardhan nav jhale haath re.","m":"They see all with an equal eye and have given up craving; every other woman is a mother to them. Their tongue never tells a lie, and their hand never takes another’s wealth."},{"d":"मोह माया व्यापे नहि जेने, दृढ वैराग्य जेना मनमां रे।\nरामनाम शुं ताळी लागी, सकळ तीरथ तेना तनमां रे॥","r":"Moh maya vyape nahi jene, dridh vairagya jena manman re,\nRamnaam shun tali lagi, sakal tirath tena tanman re.","m":"Delusion and illusion cannot touch them; firm detachment fills their mind. They are absorbed in the name of Ram, and every place of pilgrimage lives within them."},{"d":"वणलोभी ने कपटरहित छे, काम क्रोध निवार्या रे।\nभणे नरसैयो तेनुं दरसन करतां, कुळ एकोतेर तार्या रे॥","r":"Vanlobhi ne kapatrahit chhe, kaam krodh nivarya re,\nBhane Narsaiyo tenun darsan kartan, kul ekoter tarya re.","m":"They are free of greed and deceit, and have overcome lust and anger. Narsinh says: just seeing such a person saves seventy-one generations of one’s family."}]},{"id":"hanuman-chalisa","kind":"chalisa","deity":"hanuman","lang":"hi","language":"Hindi","region":"All of North India, and wherever Hindi speakers live","title":{"d":"हनुमान चालीसा","r":"Hanuman Chalisa","en":"Forty verses in praise of Shri Hanuman"},"auth":{"t":"Goswami Tulsidas, 16th century. The fortieth chaupai carries his name.","c":"attributed"},"occ":["hanuman-jayanti","sundarkand","daily"],"when":"Recited on Tuesdays and Saturdays, morning or night, and in any time of fear or difficulty. On special days many recite it seven, eleven or a hundred and eight times.","dialect":"Awadhi","notes":"Editions differ in small ways, for example “संकर सुवन केसरीनंदन” or “शंकर स्वयं केसरीनंदन” in the sixth chaupai. The two dohas at the start and the one at the end are part of the text but not counted among the forty.","refrain":null,"refrainFirst":true,"verses":[{"d":"श्रीगुरु चरन सरोज रज, निज मनु मुकुरु सुधारि।\nबरनउँ रघुबर बिमल जसु, जो दायकु फल चारि॥","r":"Shriguru charan saroj raj, nij manu mukuru sudhari,\nBaranaun Raghubar bimal jasu, jo dayaku phal chari.","m":"Cleaning the mirror of my mind with the dust of my Guru’s lotus feet, I sing the spotless glory of Shri Ram, which grants the four aims of life.","n":"दोहा"},{"d":"बुद्धिहीन तनु जानिके, सुमिरौं पवन-कुमार।\nबल बुधि बिद्या देहु मोहिं, हरहु कलेस बिकार॥","r":"Buddhiheen tanu janike, sumiraun Pavan-kumar,\nBal buddhi bidya dehu mohin, harahu kalesh bikar.","m":"Knowing how little wisdom I have, I remember the son of the Wind. Give me strength, understanding and knowledge, and take away my troubles and faults.","n":"दोहा"},{"d":"जय हनुमान ज्ञान गुन सागर।\nजय कपीस तिहुँ लोक उजागर॥","r":"Jai Hanuman gyan gun sagar,\njai Kapis tihun lok ujagar.","m":"Victory to Hanuman, ocean of wisdom and virtue! Victory to the lord of the monkeys, whose light fills the three worlds."},{"d":"राम दूत अतुलित बल धामा।\nअंजनि-पुत्र पवनसुत नामा॥","r":"Ram doot atulit bal dhama,\nAnjani-putra Pavansut nama.","m":"Ram’s messenger, home of matchless strength, known as Anjani’s son and the son of the Wind."},{"d":"महाबीर बिक्रम बजरंगी।\nकुमति निवार सुमति के संगी॥","r":"Mahabir bikram Bajrangi,\nkumati nivar sumati ke sangi.","m":"Great hero, mighty one with a body like a thunderbolt, you drive away bad thoughts and stand beside good sense."},{"d":"कंचन बरन बिराज सुबेसा।\nकानन कुंडल कुंचित केसा॥","r":"Kanchan baran biraj subesa,\nkanan kundal kunchit kesa.","m":"Golden in colour and finely dressed, with rings in your ears and curling hair."},{"d":"हाथ बज्र औ ध्वजा बिराजै।\nकाँधे मूँज जनेऊ साजै॥","r":"Haath bajra au dhwaja birajai,\nkaandhe moonj janeu saajai.","m":"The thunderbolt and the banner shine in your hands, and a sacred thread of munja grass crosses your shoulder."},{"d":"संकर सुवन केसरीनंदन।\nतेज प्रताप महा जग बंदन॥","r":"Sankar suvan Kesarinandan,\ntej pratap maha jag bandan.","m":"Born of Shankar, joy of Kesari, the whole world bows to your radiance and might."},{"d":"बिद्यावान गुनी अति चातुर।\nराम काज करिबे को आतुर॥","r":"Bidyavan guni ati chatur,\nRam kaj karibe ko aatur.","m":"Learned, virtuous and wise, you are always eager to do Ram’s work."},{"d":"प्रभु चरित्र सुनिबे को रसिया।\nराम लखन सीता मन बसिया॥","r":"Prabhu charitra sunibe ko rasiya,\nRam Lakhan Sita man basiya.","m":"You delight in hearing the Lord’s story, and Ram, Lakshman and Sita live in your heart."},{"d":"सूक्ष्म रूप धरि सियहिं दिखावा।\nबिकट रूप धरि लंक जरावा॥","r":"Sukshma roop dhari Siyahin dikhava,\nbikat roop dhari Lank jarava.","m":"Taking a tiny form you appeared before Sita; taking a terrible form you set Lanka on fire."},{"d":"भीम रूप धरि असुर सँहारे।\nरामचंद्र के काज सँवारे॥","r":"Bheem roop dhari asur sanhare,\nRamchandra ke kaj sanvare.","m":"Taking a fearsome form you destroyed the demons and completed Ramchandra’s work."},{"d":"लाय सजीवन लखन जियाये।\nश्रीरघुबीर हरषि उर लाये॥","r":"Laay Sajivan Lakhan jiyaye,\nShri Raghubir harashi ur laye.","m":"You brought the Sanjivani herb and revived Lakshman, and Shri Ram held you to his heart in joy."},{"d":"रघुपति कीन्ही बहुत बड़ाई।\nतुम मम प्रिय भरतहि सम भाई॥","r":"Raghupati keenhi bahut badai,\ntum mam priya Bharatahi sam bhai.","m":"Raghupati praised you greatly: “You are as dear to me as my brother Bharat.”"},{"d":"सहस बदन तुम्हरो जस गावैं।\nअस कहि श्रीपति कंठ लगावैं॥","r":"Sahas badan tumharo jas gavain,\nas kahi Shripati kanth lagavain.","m":"“May the thousand-mouthed Shesh sing your praise,” said the Lord, and embraced you."},{"d":"सनकादिक ब्रह्मादि मुनीसा।\nनारद सारद सहित अहीसा॥","r":"Sanakadik Brahmadi munisa,\nNarad Sarad sahit Ahisa.","m":"Sanaka and the sages, Brahma and the gods, Narad, Saraswati and the king of serpents,"},{"d":"जम कुबेर दिगपाल जहाँ ते।\nकबि कोबिद कहि सके कहाँ ते॥","r":"Jam Kuber Digpal jahan te,\nkabi kobid kahi sake kahan te.","m":"Yama, Kuber and the guardians of the directions cannot describe your glory, so how could poets and scholars?"},{"d":"तुम उपकार सुग्रीवहिं कीन्हा।\nराम मिलाय राज पद दीन्हा॥","r":"Tum upkar Sugrivahin keenha,\nRam milay raj pad deenha.","m":"You did Sugriv a great service: you brought him to Ram, and he regained his throne."},{"d":"तुम्हरो मंत्र बिभीषन माना।\nलंकेस्वर भए सब जग जाना॥","r":"Tumharo mantra Bibhishan mana,\nLankeshwar bhaye sab jag jana.","m":"Vibhishan took your advice and became king of Lanka, as the whole world knows."},{"d":"जुग सहस्र जोजन पर भानू।\nलील्यो ताहि मधुर फल जानू॥","r":"Jug sahasra jojan par bhanu,\nleelyo tahi madhur phal janu.","m":"The sun, thousands of leagues away, you swallowed, taking it for a sweet fruit."},{"d":"प्रभु मुद्रिका मेलि मुख माहीं।\nजलधि लाँघि गये अचरज नाहीं॥","r":"Prabhu mudrika meli mukh mahin,\njaladhi laanghi gaye achraj nahin.","m":"With the Lord’s ring in your mouth you leapt across the ocean. No wonder in that!"},{"d":"दुर्गम काज जगत के जेते।\nसुगम अनुग्रह तुम्हरे तेते॥","r":"Durgam kaj jagat ke jete,\nsugam anugrah tumhre tete.","m":"Every hard task in the world becomes easy by your grace."},{"d":"राम दुआरे तुम रखवारे।\nहोत न आज्ञा बिनु पैसारे॥","r":"Ram duare tum rakhvare,\nhot na agya binu paisare.","m":"You guard Ram’s door; no one enters without your leave."},{"d":"सब सुख लहै तुम्हारी सरना।\nतुम रच्छक काहू को डर ना॥","r":"Sab sukh lahai tumhari sarna,\ntum rakshak kahu ko dar na.","m":"Those who take refuge in you find every happiness. With you as protector, there is nothing to fear."},{"d":"आपन तेज सम्हारो आपै।\nतीनों लोक हाँक तें काँपै॥","r":"Aapan tej samharo aapai,\nteenon lok haank te kaanpai.","m":"Only you can hold your own power; the three worlds tremble at your roar."},{"d":"भूत पिसाच निकट नहिं आवै।\nमहाबीर जब नाम सुनावै॥","r":"Bhoot pisach nikat nahin aavai,\nMahabir jab naam sunavai.","m":"Ghosts and evil spirits stay away when the great hero’s name is spoken."},{"d":"नासै रोग हरै सब पीरा।\nजपत निरंतर हनुमत बीरा॥","r":"Nasai rog harai sab peera,\njapat nirantar Hanumat beera.","m":"Illness ends and every pain is removed by constantly repeating the name of brave Hanuman."},{"d":"संकट तें हनुमान छुड़ावै।\nमन क्रम बचन ध्यान जो लावै॥","r":"Sankat te Hanuman chhudavai,\nman kram bachan dhyan jo lavai.","m":"Hanuman frees from trouble all who remember him in thought, deed and word."},{"d":"सब पर राम तपस्वी राजा।\nतिन के काज सकल तुम साजा॥","r":"Sab par Ram tapasvi raja,\ntin ke kaj sakal tum saja.","m":"Ram, the ascetic king, is above all, and you carried out all his work."},{"d":"और मनोरथ जो कोई लावै।\nसोइ अमित जीवन फल पावै॥","r":"Aur manorath jo koi lavai,\nsoi amit jeevan phal pavai.","m":"Whoever comes to you with any wish receives the boundless fruit of life."},{"d":"चारों जुग परताप तुम्हारा।\nहै परसिद्ध जगत उजियारा॥","r":"Charon jug partap tumhara,\nhai parsiddh jagat ujiyara.","m":"Your glory shines through all four ages and lights up the world."},{"d":"साधु संत के तुम रखवारे।\nअसुर निकंदन राम दुलारे॥","r":"Sadhu sant ke tum rakhvare,\nasur nikandan Ram dulare.","m":"You protect the good and the saintly, destroy demons, and are dear to Ram."},{"d":"अष्ट सिद्धि नौ निधि के दाता।\nअस बर दीन जानकी माता॥","r":"Ashta siddhi nau nidhi ke data,\nas bar deen Janaki mata.","m":"Mother Janaki blessed you to be the giver of the eight powers and the nine treasures."},{"d":"राम रसायन तुम्हरे पासा।\nसदा रहो रघुपति के दासा॥","r":"Ram rasayan tumhre pasa,\nsada raho Raghupati ke dasa.","m":"You hold the healing nectar of Ram’s name, and remain forever Raghupati’s servant."},{"d":"तुम्हरे भजन राम को पावै।\nजनम जनम के दुख बिसरावै॥","r":"Tumhre bhajan Ram ko pavai,\njanam janam ke dukh bisravai.","m":"Through devotion to you one reaches Ram and forgets the sorrows of many lives."},{"d":"अंत काल रघुबर पुर जाई।\nजहाँ जन्म हरि-भक्त कहाई॥","r":"Ant kaal Raghubar pur jai,\njahan janma Hari-bhakt kahai.","m":"At life’s end one goes to Ram’s abode, and wherever born again is known as a devotee of Hari."},{"d":"और देवता चित्त न धरई।\nहनुमत सेइ सर्ब सुख करई॥","r":"Aur devta chitt na dharai,\nHanumat sei sarb sukh karai.","m":"Even without turning the mind to other gods, serving Hanuman brings every happiness."},{"d":"संकट कटै मिटै सब पीरा।\nजो सुमिरै हनुमत बलबीरा॥","r":"Sankat katai mitai sab peera,\njo sumirai Hanumat balbeera.","m":"Troubles are cut away and all pain ends for one who remembers mighty Hanuman."},{"d":"जै जै जै हनुमान गोसाईं।\nकृपा करहु गुरुदेव की नाईं॥","r":"Jai jai jai Hanuman Gosain,\nkripa karahu Gurudev ki nain.","m":"Victory, victory, victory to Lord Hanuman! Be gracious to me as a guru is to his disciple."},{"d":"जो सत बार पाठ कर कोई।\nछूटहि बंदि महा सुख होई॥","r":"Jo sat baar paath kar koi,\nchhootahi bandi maha sukh hoi.","m":"Whoever recites this a hundred times is freed from bondage and finds great joy."},{"d":"जो यह पढ़ै हनुमान चालीसा।\nहोय सिद्धि साखी गौरीसा॥","r":"Jo yah padhai Hanuman Chalisa,\nhoy siddhi sakhi Gaurisa.","m":"Whoever reads this Hanuman Chalisa succeeds; Shiv, lord of Gauri, is witness to it."},{"d":"तुलसीदास सदा हरि चेरा।\nकीजै नाथ हृदय महँ डेरा॥","r":"Tulsidas sada Hari chera,\nkeejai nath hriday mahan dera.","m":"Tulsidas is forever Hari’s servant. Lord, make your home in my heart."},{"d":"पवनतनय संकट हरन, मंगल मूरति रूप।\nराम लखन सीता सहित, हृदय बसहु सुर भूप॥","r":"Pavantanay sankat haran, mangal murati roop,\nRam Lakhan Sita sahit, hriday basahu sur bhoop.","m":"Son of the Wind, remover of troubles, form of all that is auspicious: king of the gods, live in my heart together with Ram, Lakshman and Sita.","n":"दोहा"}]},{"id":"asato-ma-sadgamaya","kind":"mantra","deity":"ishvar","lang":"sa","language":"Sanskrit (Vedic)","region":"All of India","title":{"d":"असतो मा सद्गमय","r":"Asato Ma Sadgamaya","en":"From darkness to light"},"auth":{"t":"Brihadaranyaka Upanishad 1.3.28","c":"known"},"occ":["morning","daily"],"when":"Recited at the start of study, at school assemblies and at the opening of gatherings.","form":"Shanti mantra","refrain":null,"refrainFirst":true,"verses":[{"d":"ॐ असतो मा सद्गमय।\nतमसो मा ज्योतिर्गमय।\nमृत्योर्मा अमृतं गमय।\nॐ शान्तिः शान्तिः शान्तिः॥","r":"Om asato ma sadgamaya,\nTamaso ma jyotirgamaya,\nMrityorma amritam gamaya,\nOm shantih shantih shantih.","m":"Lead me from the unreal to the real. Lead me from darkness to light. Lead me from death to immortality. Om, peace, peace, peace."}]},{"id":"gayatri-mantra","kind":"mantra","deity":"surya","lang":"sa","language":"Sanskrit (Vedic)","region":"All of India","title":{"d":"गायत्री मंत्र","r":"Gayatri Mantra","en":"The Vedic prayer for a clear mind"},"auth":{"t":"Rishi Vishwamitra, Rigveda 3.62.10","c":"attributed"},"occ":["morning","daily"],"when":"Recited at sunrise and at the sandhya prayers, before study, and in japa of 108 repetitions.","notes":"The opening “ॐ भूर्भुवः स्वः” is added before the Rigvedic verse when it is chanted.","refrain":null,"refrainFirst":true,"verses":[{"d":"ॐ भूर्भुवः स्वः।\nतत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि।\nधियो यो नः प्रचोदयात्॥","r":"Om bhur bhuvah svah,\nTat savitur varenyam bhargo devasya dhimahi,\nDhiyo yo nah prachodayat.","m":"Om. Earth, sky and heaven. We meditate on the glorious light of the divine Savitr, the Sun, worthy of all worship. May he inspire and guide our minds."}]},{"id":"hare-krishna-mahamantra","kind":"mantra","deity":"krishna","lang":"sa","language":"Sanskrit","region":"All of India and worldwide","title":{"d":"हरे राम हरे कृष्ण","r":"Hare Rama Hare Krishna","en":"The mahamantra of sixteen names"},"auth":{"t":"Kali-Santarana Upanishad","c":"known"},"occ":["janmashtami","daily"],"when":"Repeated in japa on a mala of 108 beads and sung in kirtan.","form":"Mahamantra","notes":"The Kali-Santarana Upanishad gives it beginning with “Hare Rama”; ISKCON and many kirtan groups begin with “Hare Krishna”.","refrain":null,"refrainFirst":true,"verses":[{"d":"हरे राम हरे राम राम राम हरे हरे।\nहरे कृष्ण हरे कृष्ण कृष्ण कृष्ण हरे हरे॥","r":"Hare Rama Hare Rama, Rama Rama Hare Hare,\nHare Krishna Hare Krishna, Krishna Krishna Hare Hare.","m":"A call to the Lord through his names Hari, Ram and Krishna, repeated with love until the mind rests in them."}]},{"id":"karpur-gauram","kind":"mantra","deity":"shiv","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"कर्पूरगौरं करुणावतारं","r":"Karpur Gauram Karunavataram","en":"Closing verse to Shiv"},"auth":{"t":"Traditional Sanskrit verse","c":"traditional"},"occ":["closing","mahashivratri","shravan"],"when":"Recited in many homes and temples as the flame is offered at the end of the aarti, whichever deity’s aarti came before it.","form":"Shloka","refrain":null,"refrainFirst":true,"verses":[{"d":"कर्पूरगौरं करुणावतारं संसारसारं भुजगेन्द्रहारम्।\nसदा वसन्तं हृदयारविन्दे भवं भवानीसहितं नमामि॥","r":"Karpuragauram karunavataram, samsarasaram bhujagendraharam,\nSada vasantam hridayaravinde, Bhavam Bhavanisahitam namami.","m":"I bow to Shiv, fair as camphor, compassion embodied, the essence of the world, garlanded with the king of serpents, who lives always in the lotus of the heart together with Bhavani."}]},{"id":"mahamrityunjaya-mantra","kind":"mantra","deity":"shiv","lang":"sa","language":"Sanskrit (Vedic)","region":"All of India","title":{"d":"महामृत्युंजय मंत्र","r":"Mahamrityunjaya Mantra","en":"The great prayer for victory over death"},"auth":{"t":"Rishi Vasishtha, Rigveda 7.59.12","c":"attributed"},"occ":["shravan","mahashivratri","daily"],"when":"Chanted for healing, protection and peace, especially when someone is unwell, often 108 times on a rudraksha mala.","refrain":null,"refrainFirst":true,"verses":[{"d":"ॐ त्र्यम्बकं यजामहे सुगन्धिं पुष्टिवर्धनम्।\nउर्वारुकमिव बन्धनान्मृत्योर्मुक्षीय माऽमृतात्॥","r":"Om tryambakam yajamahe sugandhim pushtivardhanam,\nUrvarukamiva bandhanan mrityor mukshiya ma’mritat.","m":"We worship the three-eyed one, fragrant, who nourishes all beings. As a ripe cucumber is freed from its vine, may he free us from death, and never from immortality."}]},{"id":"saraswati-vandana","kind":"mantra","deity":"saraswati","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"या कुन्देन्दुतुषारहारधवला","r":"Ya Kundendu Tushar Haar Dhavala","en":"Saraswati Vandana"},"auth":{"t":"Traditional Sanskrit shloka","c":"traditional"},"occ":["basant-panchami","morning","daily"],"when":"Recited at school assemblies, before study and exams, and in Saraswati Puja on Basant Panchami.","form":"Vandana","refrain":null,"refrainFirst":true,"verses":[{"d":"या कुन्देन्दुतुषारहारधवला या शुभ्रवस्त्रावृता।\nया वीणावरदण्डमण्डितकरा या श्वेतपद्मासना॥\nया ब्रह्माच्युतशंकरप्रभृतिभिर्देवैः सदा वन्दिता।\nसा मां पातु सरस्वती भगवती निःशेषजाड्यापहा॥","r":"Ya kundendu tushara hara dhavala, ya shubhra vastravrita,\nYa veena varadanda manditakara, ya shveta padmasana,\nYa Brahmachyuta Shankara prabhritibhir devaih sada vandita,\nSa mam patu Saraswati Bhagavati nihshesha jadyapaha.","m":"She who is white as jasmine, the moon, snow and a string of pearls, dressed in white; whose hands are graced by the veena and the staff of blessing; who sits on a white lotus; who is always worshipped by Brahma, Vishnu, Shiv and all the gods: may that Goddess Saraswati, who removes all dullness of mind, protect me."}]},{"id":"sarve-bhavantu-sukhinah","kind":"mantra","deity":"ishvar","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"सर्वे भवन्तु सुखिनः","r":"Sarve Bhavantu Sukhinah","en":"A prayer for the happiness of all"},"auth":{"t":"Traditional Sanskrit prayer","c":"traditional"},"occ":["closing","meals","daily"],"when":"A prayer for the welfare of every being, said at the end of puja, satsang or a meal.","form":"Shanti mantra","refrain":null,"refrainFirst":true,"verses":[{"d":"ॐ सर्वे भवन्तु सुखिनः सर्वे सन्तु निरामयाः।\nसर्वे भद्राणि पश्यन्तु मा कश्चिद्दुःखभाग्भवेत्॥\nॐ शान्तिः शान्तिः शान्तिः॥","r":"Om sarve bhavantu sukhinah, sarve santu niramayah,\nSarve bhadrani pashyantu, ma kashchid duhkhabhagbhavet.\nOm shantih shantih shantih.","m":"May all be happy; may all be free from illness. May all see only what is good, and may no one suffer. Om, peace, peace, peace."}]},{"id":"tvameva-mata","kind":"mantra","deity":"ishvar","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"त्वमेव माता च पिता त्वमेव","r":"Tvameva Mata Cha Pita Tvameva","en":"You alone are everything to me"},"auth":{"t":"Traditional Sanskrit verse, also found in the Pandava Gita","c":"traditional"},"occ":["closing","morning","daily"],"when":"Sung at the end of the aarti in many homes, and as a morning prayer in schools.","form":"Shloka","refrain":null,"refrainFirst":true,"verses":[{"d":"त्वमेव माता च पिता त्वमेव। त्वमेव बन्धुश्च सखा त्वमेव॥\nत्वमेव विद्या द्रविणं त्वमेव। त्वमेव सर्वं मम देव देव॥","r":"Tvameva mata cha pita tvameva, tvameva bandhushcha sakha tvameva,\nTvameva vidya dravinam tvameva, tvameva sarvam mama deva deva.","m":"You alone are my mother and my father, you alone my family and my friend. You alone are my knowledge and my wealth. You are everything to me, God of gods."}]},{"id":"vakratunda-mahakaya","kind":"mantra","deity":"ganesh","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"वक्रतुण्ड महाकाय","r":"Vakratunda Mahakaya","en":"Prayer to Ganesh before any work"},"auth":{"t":"Traditional Sanskrit shloka","c":"traditional"},"occ":["morning","ganesh-chaturthi","daily"],"when":"Said before starting any work, journey, exam or puja, so that it goes ahead without obstacles.","form":"Shloka","refrain":null,"refrainFirst":true,"verses":[{"d":"वक्रतुण्ड महाकाय सूर्यकोटि समप्रभ।\nनिर्विघ्नं कुरु मे देव सर्वकार्येषु सर्वदा॥","r":"Vakratunda mahakaya suryakoti samaprabha,\nNirvighnam kuru me deva sarvakaryeshu sarvada.","m":"O Lord with the curved trunk and mighty body, radiant as millions of suns: keep every obstacle away from all that I do, always."}]},{"id":"madhurashtakam","kind":"stotra","deity":"krishna","lang":"sa","language":"Sanskrit","region":"All of India, especially the Pushti Marg tradition","title":{"d":"मधुराष्टकम्","r":"Madhurashtakam (Adharam Madhuram)","en":"Eight verses on Krishna’s sweetness"},"auth":{"t":"Shri Vallabhacharya, around 1500","c":"attributed"},"occ":["janmashtami","holi","daily"],"when":"Sung in Krishna worship, on Janmashtami and at satsangs. Its simple repeating pattern makes it easy for children to learn.","form":"Ashtakam","notes":"Every verse ends “मधुराधिपतेरखिलं मधुरम्”: everything about the Lord of sweetness is sweet.","refrain":null,"refrainFirst":true,"verses":[{"d":"अधरं मधुरं वदनं मधुरं नयनं मधुरं हसितं मधुरम्।\nहृदयं मधुरं गमनं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Adharam madhuram vadanam madhuram, nayanam madhuram hasitam madhuram,\nHridayam madhuram gamanam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet are his lips, sweet his face, sweet his eyes, sweet his smile; sweet his heart, sweet his walk. Everything about the Lord of sweetness is sweet."},{"d":"वचनं मधुरं चरितं मधुरं वसनं मधुरं वलितं मधुरम्।\nचलितं मधुरं भ्रमितं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Vachanam madhuram charitam madhuram, vasanam madhuram valitam madhuram,\nChalitam madhuram bhramitam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet are his words, his deeds, his clothes and the way he turns; sweet his movements and his wanderings. Everything about the Lord of sweetness is sweet."},{"d":"वेणुर्मधुरो रेणुर्मधुरः पाणिर्मधुरः पादौ मधुरौ।\nनृत्यं मधुरं सख्यं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Venurmadhuro renurmadhurah, panirmadhurah padau madhurau,\nNrityam madhuram sakhyam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet is his flute, sweet the dust of his feet; sweet his hands, sweet his feet; sweet his dance and his friendship. Everything about the Lord of sweetness is sweet."},{"d":"गीतं मधुरं पीतं मधुरं भुक्तं मधुरं सुप्तं मधुरम्।\nरूपं मधुरं तिलकं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Gitam madhuram pitam madhuram, bhuktam madhuram suptam madhuram,\nRoopam madhuram tilakam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet is his singing, his drinking, his eating and his sleep; sweet his form, sweet the tilak on his brow. Everything about the Lord of sweetness is sweet."},{"d":"करणं मधुरं तरणं मधुरं हरणं मधुरं रमणं मधुरम्।\nवमितं मधुरं शमितं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Karanam madhuram taranam madhuram, haranam madhuram ramanam madhuram,\nVamitam madhuram shamitam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet are his doings, his rescues, the way he steals hearts and his play; sweet what he gives away and his calm. Everything about the Lord of sweetness is sweet."},{"d":"गुञ्जा मधुरा माला मधुरा यमुना मधुरा वीची मधुरा।\nसलिलं मधुरं कमलं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Gunja madhura mala madhura, Yamuna madhura vichi madhura,\nSalilam madhuram kamalam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet is his necklace of gunja berries, sweet his garland; sweet the Yamuna and her ripples, sweet her water and her lotuses. Everything about the Lord of sweetness is sweet."},{"d":"गोपी मधुरा लीला मधुरा युक्तं मधुरं मुक्तं मधुरम्।\nदृष्टं मधुरं शिष्टं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Gopi madhura lila madhura, yuktam madhuram muktam madhuram,\nDrishtam madhuram shishtam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet are the gopis and his play with them; sweet his meetings and his partings; sweet his glance and his courtesy. Everything about the Lord of sweetness is sweet."},{"d":"गोपा मधुरा गावो मधुरा यष्टिर्मधुरा सृष्टिर्मधुरा।\nदलितं मधुरं फलितं मधुरं मधुराधिपतेरखिलं मधुरम्॥","r":"Gopa madhura gavo madhura, yashtirmadhura srishtirmadhura,\nDalitam madhuram phalitam madhuram, Madhuradhipaterakhilam madhuram.","m":"Sweet are the cowherds, sweet the cows, sweet his staff and all creation; sweet what he crushes and what he brings to fruit. Everything about the Lord of sweetness is sweet."}]},{"id":"nirvana-shatakam","kind":"stotra","deity":"shiv","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"निर्वाणषट्कम्","r":"Nirvana Shatakam (Shivoham)","en":"Six verses on the true Self"},"auth":{"t":"Traditionally attributed to Adi Shankaracharya","c":"attributed"},"occ":["mahashivratri","daily"],"when":"A hymn of Advaita Vedanta, chanted in meditation and on Maha Shivratri. Here “Shiv” means the pure Self, beyond body and mind.","notes":"Also called Atma Shatakam. The last verse has variants, such as “न चासङ्गतं नैव मुक्तिर्न मेयः”.","refrain":null,"refrainFirst":true,"verses":[{"d":"मनोबुद्ध्यहङ्कारचित्तानि नाहं न च श्रोत्रजिह्वे न च घ्राणनेत्रे।\nन च व्योम भूमिर्न तेजो न वायुः चिदानन्दरूपः शिवोऽहं शिवोऽहम्॥","r":"Mano buddhyahankara chittani naham, na cha shrotra jihve na cha ghrana netre,\nNa cha vyoma bhumir na tejo na vayuh, chidananda roopah Shivo’ham Shivo’ham.","m":"I am not the mind, intellect, ego or memory; not the ears, tongue, nose or eyes; not space, earth, fire or air. I am consciousness and bliss. I am Shiv, I am Shiv."},{"d":"न च प्राणसंज्ञो न वै पञ्चवायुः न वा सप्तधातुर्न वा पञ्चकोशः।\nन वाक्पाणिपादं न चोपस्थपायू चिदानन्दरूपः शिवोऽहं शिवोऽहम्॥","r":"Na cha prana sanjno na vai panchavayuh, na va saptadhatur na va panchakoshah,\nNa vak pani padam na chopasthapayu, chidananda roopah Shivo’ham Shivo’ham.","m":"I am not the breath of life nor the five vital airs, not the seven elements of the body nor its five sheaths, not speech, hands, feet or any organ of action. I am consciousness and bliss. I am Shiv, I am Shiv."},{"d":"न मे द्वेषरागौ न मे लोभमोहौ मदो नैव मे नैव मात्सर्यभावः।\nन धर्मो न चार्थो न कामो न मोक्षः चिदानन्दरूपः शिवोऽहं शिवोऽहम्॥","r":"Na me dvesharagau na me lobhamohau, mado naiva me naiva matsarya bhavah,\nNa dharmo na chartho na kamo na mokshah, chidananda roopah Shivo’ham Shivo’ham.","m":"I have no hatred or attachment, no greed or delusion, no pride and no envy. I am not duty, wealth, desire, or even liberation. I am consciousness and bliss. I am Shiv, I am Shiv."},{"d":"न पुण्यं न पापं न सौख्यं न दुःखं न मन्त्रो न तीर्थं न वेदा न यज्ञाः।\nअहं भोजनं नैव भोज्यं न भोक्ता चिदानन्दरूपः शिवोऽहं शिवोऽहम्॥","r":"Na punyam na papam na saukhyam na duhkham, na mantro na tirtham na veda na yajnah,\nAham bhojanam naiva bhojyam na bhokta, chidananda roopah Shivo’ham Shivo’ham.","m":"Not merit or sin, not pleasure or pain; not mantra, pilgrimage, scripture or sacrifice. I am not the eating, the food, or the one who eats. I am consciousness and bliss. I am Shiv, I am Shiv."},{"d":"न मे मृत्युशङ्का न मे जातिभेदः पिता नैव मे नैव माता न जन्म।\nन बन्धुर्न मित्रं गुरुर्नैव शिष्यः चिदानन्दरूपः शिवोऽहं शिवोऽहम्॥","r":"Na me mrityushanka na me jatibhedah, pita naiva me naiva mata na janma,\nNa bandhur na mitram gurur naiva shishyah, chidananda roopah Shivo’ham Shivo’ham.","m":"I have no fear of death and no divisions of birth; no father, no mother, no birth at all; no kin, no friend, no teacher and no disciple. I am consciousness and bliss. I am Shiv, I am Shiv."},{"d":"अहं निर्विकल्पो निराकाररूपो विभुत्वाच्च सर्वत्र सर्वेन्द्रियाणाम्।\nसदा मे समत्वं न मुक्तिर्न बन्धः चिदानन्दरूपः शिवोऽहं शिवोऽहम्॥","r":"Aham nirvikalpo nirakara roopo, vibhutvachcha sarvatra sarvendriyanam,\nSada me samatvam na muktir na bandhah, chidananda roopah Shivo’ham Shivo’ham.","m":"I am free of all doubt and without form, present everywhere and behind every sense. I am always the same; for me there is no freedom and no bondage. I am consciousness and bliss. I am Shiv, I am Shiv."}]},{"id":"shiv-rudrashtakam","kind":"stotra","deity":"shiv","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"श्री रुद्राष्टकम्","r":"Shri Rudrashtakam (Namamishamishan)","en":"Eight verses to Shiv as Rudra"},"auth":{"t":"Goswami Tulsidas, from the Uttar Kand of the Ramcharitmanas","c":"known"},"occ":["mahashivratri","shravan","daily"],"when":"Sung in Shiv puja, on Mondays, through Sawan and on Maha Shivratri. In the Manas, a Brahmin sings it to win Shiv’s mercy for his disciple.","form":"Stuti","notes":"Unlike the rest of the Manas it is in Sanskrit. Some editions print the second verse as “गिरा ग्यान गोतीतमीशं गिरीशं”.","refrain":null,"refrainFirst":true,"verses":[{"d":"नमामीशमीशान निर्वाणरूपं। विभुं व्यापकं ब्रह्म वेदस्वरूपं॥\nनिजं निर्गुणं निर्विकल्पं निरीहं। चिदाकाशमाकाशवासं भजेऽहं॥","r":"Namamishamishan nirvanaroopam, vibhum vyapakam Brahma Vedasvaroopam,\nNijam nirgunam nirvikalpam niriham, chidakashamakashavasam bhaje’ham.","m":"I bow to the Lord of all, whose very form is liberation: all-pervading, the Brahman whose form is the Veda. I worship him who is the Self, beyond qualities, doubt and desire, pure consciousness spread like the sky."},{"d":"निराकारमोंकारमूलं तुरीयं। गिरा ज्ञान गोतीतमीशं गिरीशं॥\nकरालं महाकाल कालं कृपालं। गुणागार संसारपारं नतोऽहं॥","r":"Nirakaram Omkaramoolam turiyam, gira gyan gotitamisham Girisham,\nKaralam Mahakal kalam kripalam, gunagar sansaraparam nato’ham.","m":"Formless, the root of Om, beyond the three states of waking, dream and sleep; beyond speech, thought and the senses, lord of the mountain. Fearsome, the death of Death, yet full of mercy, home of all virtues, beyond the world: to him I bow."},{"d":"तुषाराद्रि संकाश गौरं गभीरं। मनोभूत कोटि प्रभा श्री शरीरं॥\nस्फुरन्मौलि कल्लोलिनी चारु गंगा। लसद्भालबालेन्दु कंठे भुजंगा॥","r":"Tusharadri sankash gauram gabhiram, manobhoot koti prabha shri shariram,\nSphuranmauli kallolini charu Ganga, lasadbhalabalendu kanthe bhujanga.","m":"Fair as the snowy Himalaya and deep beyond measure, his body shines with the beauty of millions of Kamadevs. The lovely Ganga ripples on his head, the young moon glows on his brow, and serpents circle his neck."},{"d":"चलत्कुण्डलं भ्रू सुनेत्रं विशालं। प्रसन्नाननं नीलकंठं दयालं॥\nमृगाधीशचर्माम्बरं मुण्डमालं। प्रियं शंकरं सर्वनाथं भजामि॥","r":"Chalatkundalam bhru sunetram vishalam, prasannananam Neelkantham dayalam,\nMrigadhishacharmambaram mundamalam, priyam Shankaram sarvanatham bhajami.","m":"Earrings swaying, fine brows and wide, lovely eyes, a joyful face, a blue throat and a kind heart; clothed in a lion’s skin and garlanded with skulls: I worship beloved Shankar, lord of all."},{"d":"प्रचंडं प्रकृष्टं प्रगल्भं परेशं। अखंडं अजं भानुकोटिप्रकाशं॥\nत्रयः शूल निर्मूलनं शूलपाणिं। भजेऽहं भवानीपतिं भावगम्यं॥","r":"Prachandam prakrishtam pragalbham paresham, akhandam ajam bhanukotiprakasham,\nTrayah shool nirmoolanam shoolapanim, bhaje’ham Bhavanipatim bhavagamyam.","m":"Fierce, supreme, fearless, the highest lord; whole, unborn, bright as millions of suns; the trident-holder who uproots the three kinds of suffering. I worship Bhavani’s lord, who is reached through love."},{"d":"कलातीत कल्याण कल्पान्तकारी। सदा सज्जनानन्ददाता पुरारी॥\nचिदानंदसंदोह मोहापहारी। प्रसीद प्रसीद प्रभो मन्मथारी॥","r":"Kalatit kalyan kalpantakari, sada sajjanananda data Purari,\nChidananda sandoha mohapahari, prasida prasida prabho Manmathari.","m":"Beyond time and parts, all goodness, who brings each age to its close; giver of joy to the good, destroyer of Tripura; mass of consciousness and bliss who removes delusion: be pleased, be pleased, O Lord who burned Kamadev."},{"d":"न यावत् उमानाथ पादारविन्दं। भजन्तीह लोके परे वा नराणां॥\nन तावत्सुखं शान्ति सन्तापनाशं। प्रसीद प्रभो सर्वभूताधिवासं॥","r":"Na yavat Umanath padaravindam, bhajantiha loke pare va naranam,\nNa tavat sukham shanti santapanasham, prasida prabho sarvabhootadhivasam.","m":"Until people worship the lotus feet of Uma’s lord, they find no happiness or peace in this world or the next, and their pain does not end. Be pleased, Lord who lives in every being."},{"d":"न जानामि योगं जपं नैव पूजां। नतोऽहं सदा सर्वदा शम्भु तुभ्यं॥\nजरा जन्म दुःखौघ तातप्यमानं। प्रभो पाहि आपन्नमामीश शंभो॥","r":"Na janami yogam japam naiva pujam, nato’ham sada sarvada Shambhu tubhyam,\nJara janma duhkhaugha tatapyamanam, prabho pahi apannamamisha Shambho.","m":"I know no yoga, no japa, no proper worship; I only bow to you, always, Shambhu. I burn in the flood of sorrow of birth and old age: protect me, Lord, for I have come to you in distress."},{"d":"रुद्राष्टकमिदं प्रोक्तं विप्रेण हरतोषये।\nये पठन्ति नरा भक्त्या तेषां शम्भुः प्रसीदति॥","r":"Rudrashtakamidam proktam viprena haratoshaye,\nye pathanti nara bhaktya tesham Shambhuh prasidati.","m":"This Rudrashtakam was sung by a Brahmin to please Shiv. Shambhu is pleased with all who recite it with devotion.","n":"फल"}]},{"id":"shiva-panchakshara-stotram","kind":"stotra","deity":"shiv","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"शिवपञ्चाक्षर स्तोत्रम्","r":"Shiva Panchakshara Stotram","en":"A hymn on the five syllables of Namah Shivaya"},"auth":{"t":"Traditionally attributed to Adi Shankaracharya","c":"attributed"},"occ":["mahashivratri","shravan","daily"],"when":"Recited in Shiv puja and on Mondays. Each verse is built on one syllable of the mantra: न, म, शि, वा, य.","notes":"Verse three is sometimes printed with “गौरीवदनाब्जबृन्द”.","refrain":null,"refrainFirst":true,"verses":[{"d":"नागेन्द्रहाराय त्रिलोचनाय भस्माङ्गरागाय महेश्वराय।\nनित्याय शुद्धाय दिगम्बराय तस्मै नकाराय नमः शिवाय॥","r":"Nagendraharaya trilochanaya, bhasmangaragaya Maheshwaraya,\nNityaya shuddhaya digambaraya, tasmai nakaraya namah Shivaya.","m":"To the three-eyed great lord who wears the king of serpents as a garland and sacred ash on his body; eternal, pure, clothed only by the directions: to that Shiv, the syllable “Na”, I bow."},{"d":"मन्दाकिनीसलिलचन्दनचर्चिताय नन्दीश्वरप्रमथनाथमहेश्वराय।\nमन्दारपुष्पबहुपुष्पसुपूजिताय तस्मै मकाराय नमः शिवाय॥","r":"Mandakinisalila chandana charchitaya, Nandishwara pramathanatha Maheshwaraya,\nMandara pushpa bahupushpa supujitaya, tasmai makaraya namah Shivaya.","m":"Bathed in the Ganga and anointed with sandal paste, lord of Nandi and of his hosts, worshipped with mandara and countless other flowers: to that Shiv, the syllable “Ma”, I bow."},{"d":"शिवाय गौरीवदनाब्जवृन्दसूर्याय दक्षाध्वरनाशकाय।\nश्रीनीलकण्ठाय वृषध्वजाय तस्मै शिकाराय नमः शिवाय॥","r":"Shivaya Gauri vadanabja vrinda suryaya, Dakshadhvara nashakaya,\nShri Neelakanthaya vrishadhvajaya, tasmai shikaraya namah Shivaya.","m":"To the auspicious one, the sun at whose rising Gauri’s lotus face blooms, who ended Daksha’s sacrifice; to the blue-throated one whose banner bears the bull: to that Shiv, the syllable “Shi”, I bow."},{"d":"वसिष्ठकुम्भोद्भवगौतमार्यमुनीन्द्रदेवार्चितशेखराय।\nचन्द्रार्कवैश्वानरलोचनाय तस्मै वकाराय नमः शिवाय॥","r":"Vasishtha kumbhodbhava Gautamarya munindra devarchita shekharaya,\nChandrarka vaishvanara lochanaya, tasmai vakaraya namah Shivaya.","m":"Whose head is worshipped by Vasishtha, Agastya, Gautam and the great sages and gods; whose three eyes are the moon, the sun and fire: to that Shiv, the syllable “Va”, I bow."},{"d":"यक्षस्वरूपाय जटाधराय पिनाकहस्ताय सनातनाय।\nदिव्याय देवाय दिगम्बराय तस्मै यकाराय नमः शिवाय॥","r":"Yakshasvaroopaya jatadharaya, pinakahastaya sanatanaya,\nDivyaya devaya digambaraya, tasmai yakaraya namah Shivaya.","m":"Who appeared as a yaksha, wears matted hair and holds the Pinaka bow, the eternal one; divine, radiant, clothed by the directions: to that Shiv, the syllable “Ya”, I bow."},{"d":"पञ्चाक्षरमिदं पुण्यं यः पठेच्छिवसन्निधौ।\nशिवलोकमवाप्नोति शिवेन सह मोदते॥","r":"Panchaksharamidam punyam yah pathechchhivasannidhau,\nShivalokamavapnoti Shivena saha modate.","m":"Whoever recites this sacred hymn of the five syllables near Shiv reaches Shiv’s world and rejoices with him.","n":"फल"}]},{"id":"shri-ramchandra-kripalu","kind":"stotra","deity":"ram","lang":"hi","language":"Hindi","region":"North India","title":{"d":"श्रीरामचन्द्र कृपालु भजु मन","r":"Shri Ramchandra Kripalu Bhaju Man","en":"Hymn to Shri Ram"},"auth":{"t":"Goswami Tulsidas, from the Vinaya Patrika","c":"known"},"occ":["ram-navami","dussehra","diwali","sundarkand"],"when":"Strictly a stuti, not an aarti, but it is the piece most often sung at Ram’s aarti, at Ramayan path and on Ram Navami.","form":"Stuti","dialect":"Braj Bhasha, heavily Sanskritised","refrain":null,"refrainFirst":true,"verses":[{"d":"श्रीरामचन्द्र कृपालु भजु मन, हरण भवभय दारुणम्।\nनवकंज लोचन कंज मुख, कर कंज पद कंजारुणम्॥","r":"Shri Ramchandra kripalu bhaju man, haran bhavbhay daarunam,\nNavkanj lochan kanj mukh, kar kanj pad kanjarunam.","m":"O mind, worship the compassionate Shri Ramchandra, who removes the terrible fear of worldly life: eyes like fresh lotuses, a lotus face, lotus hands and feet like red lotuses."},{"d":"कंदर्प अगणित अमित छवि, नवनील नीरद सुन्दरम्।\nपट पीत मानहुँ तड़ित रुचि, शुचि नौमि जनक सुतावरम्॥","r":"Kandarp aganit amit chhavi, navneel neerad sundaram,\nPat peet maanahun tadit ruchi, shuchi naumi Janak sutavaram.","m":"His beauty outshines countless Kamadevs; he is lovely as a fresh dark rain-cloud, and his yellow robe gleams like lightning. I bow to that pure one, husband of Janak’s daughter."},{"d":"भजु दीनबन्धु दिनेश दानव, दैत्यवंश निकन्दनम्।\nरघुनन्द आनन्दकन्द कोशलचन्द, दशरथ नन्दनम्॥","r":"Bhaju deenbandhu dinesh daanav, daityavansh nikandanam,\nRaghunand anandkand Koshalchand, Dashrath nandanam.","m":"Worship the friend of the humble, radiant as the sun, who uprooted the clans of demons: joy of the Raghus, root of bliss, moon of Koshal, son of Dasharath."},{"d":"सिर मुकुट कुण्डल तिलक चारु, उदारु अंग विभूषणम्।\nआजानुभुज शर चाप धर, संग्राम जित खरदूषणम्॥","r":"Sir mukut kundal tilak chaaru, udaaru ang vibhooshanam,\nAajanubhuj shar chaap dhar, sangram jit Khar-Dooshanam.","m":"A crown on his head, earrings and a graceful tilak, fine ornaments on every limb; arms reaching to his knees, holding bow and arrows, he defeated Khar and Dooshan in battle."},{"d":"इति वदति तुलसीदास शंकर, शेष मुनि मन रंजनम्।\nमम हृदय कंज निवास कुरु, कामादि खलदल गंजनम्॥","r":"Iti vadati Tulsidas Shankar, Shesh muni man ranjanam,\nMam hriday kanj nivaas kuru, kaamaadi khaldal ganjanam.","m":"So says Tulsidas: delight of the hearts of Shankar, Shesh and the sages, make your home in the lotus of my heart and destroy the wicked host of desire and the other vices."}]},{"id":"bhagavad-gita","kind":"granth","deity":"krishna","lang":"sa","language":"Sanskrit","region":"All of India","title":{"d":"श्रीमद्भगवद्गीता","r":"Shrimad Bhagavad Gita","en":"Krishna’s teaching to Arjun on the field of Kurukshetra"},"auth":{"t":"Ved Vyas, in the Bhishma Parva of the Mahabharata","c":"attributed"},"occ":["gita-jayanti","daily"],"when":"Many read a chapter a day, recite the whole Gita on Gita Jayanti, and return to it all their lives.","notes":"700 verses in 18 chapters. Chapters are added one at a time, each with the Sanskrit, a singable Roman version and an English meaning for every verse.","chapters":[{"n":1,"d":"अर्जुनविषादयोग","r":"Arjun Vishad Yog","en":"Arjun’s despair","count":47},{"n":2,"d":"सांख्ययोग","r":"Sankhya Yog","en":"The yoga of knowledge","count":72},{"n":3,"d":"कर्मयोग","r":"Karma Yog","en":"The yoga of action","count":43},{"n":4,"d":"ज्ञानकर्मसंन्यासयोग","r":"Gyan Karma Sanyas Yog","en":"Knowledge and the renunciation of action","count":42},{"n":5,"d":"कर्मसंन्यासयोग","r":"Karma Sanyas Yog","en":"The yoga of renunciation","count":29},{"n":6,"d":"आत्मसंयमयोग","r":"Atma Sanyam Yog","en":"The yoga of meditation","count":47},{"n":7,"d":"ज्ञानविज्ञानयोग","r":"Gyan Vigyan Yog","en":"Knowledge and realisation","count":30},{"n":8,"d":"अक्षरब्रह्मयोग","r":"Akshar Brahma Yog","en":"The imperishable Brahman","count":28},{"n":9,"d":"राजविद्याराजगुह्ययोग","r":"Rajvidya Rajguhya Yog","en":"The royal knowledge and the royal secret","count":34},{"n":10,"d":"विभूतियोग","r":"Vibhuti Yog","en":"The divine glories","count":42},{"n":11,"d":"विश्वरूपदर्शनयोग","r":"Vishwaroop Darshan Yog","en":"The vision of the cosmic form","count":55},{"n":12,"d":"भक्तियोग","r":"Bhakti Yog","en":"The yoga of devotion","count":20,"verses":[{"d":"एवं सततयुक्ता ये भक्तास्त्वां पर्युपासते।\nये चाप्यक्षरमव्यक्तं तेषां के योगवित्तमाः॥","r":"Evam satatayukta ye bhaktastvam paryupasate,\nYe chapyaksharamavyaktam tesham ke yogavittamah.","m":"Some devotees worship you this way, always united with you; others worship the imperishable, the unmanifest. Which of them know yoga best?","n":"१२.१","sp":{"d":"अर्जुन उवाच","r":"Arjun said"}},{"d":"मय्यावेश्य मनो ये मां नित्ययुक्ता उपासते।\nश्रद्धया परयोपेतास्ते मे युक्ततमा मताः॥","r":"Mayyaveshya mano ye mam nityayukta upasate,\nShraddhaya parayopetaste me yuktatama matah.","m":"Those who fix their minds on me and worship me, always devoted and filled with the highest faith: I consider them the most perfect in yoga.","n":"१२.२","sp":{"d":"श्रीभगवानुवाच","r":"The Lord said"}},{"d":"ये त्वक्षरमनिर्देश्यमव्यक्तं पर्युपासते।\nसर्वत्रगमचिन्त्यं च कूटस्थमचलं ध्रुवम्॥","r":"Ye tvaksharamanirdeshyamavyaktam paryupasate,\nSarvatragamachintyam cha kootasthamachalam dhruvam.","m":"But those who worship the imperishable, the indescribable, the unmanifest, present everywhere, beyond thought, unchanging, unmoving and eternal,","n":"१२.३"},{"d":"संनियम्येन्द्रियग्रामं सर्वत्र समबुद्धयः।\nते प्राप्नुवन्ति मामेव सर्वभूतहिते रताः॥","r":"Sanniyamyendriyagramam sarvatra samabuddhayah,\nTe prapnuvanti mameva sarvabhootahite ratah.","m":"who restrain all their senses, stay even-minded everywhere and delight in the good of all beings: they too come to me.","n":"१२.४"},{"d":"क्लेशोऽधिकतरस्तेषामव्यक्तासक्तचेतसाम्।\nअव्यक्ता हि गतिर्दुःखं देहवद्भिरवाप्यते॥","r":"Klesho’dhikatarasteshamavyaktasaktachetasam,\nAvyakta hi gatirduhkham dehavadbhiravapyate.","m":"But the way is harder for those whose minds are set on the unmanifest, for embodied beings reach that formless goal only with great difficulty.","n":"१२.५"},{"d":"ये तु सर्वाणि कर्माणि मयि संन्यस्य मत्पराः।\nअनन्येनैव योगेन मां ध्यायन्त उपासते॥","r":"Ye tu sarvani karmani mayi sannyasya matparah,\nAnanyenaiva yogena mam dhyayanta upasate.","m":"Those who offer all their actions to me, hold me as their highest goal, and worship me with undivided devotion, meditating on me,","n":"१२.६"},{"d":"तेषामहं समुद्धर्ता मृत्युसंसारसागरात्।\nभवामि नचिरात्पार्थ मय्यावेशितचेतसाम्॥","r":"Teshamaham samuddharta mrityusamsarasagarat,\nBhavami nachiratpartha mayyaveshitachetasam.","m":"for them, whose minds have entered into me, I soon become the one who lifts them out of the ocean of death and rebirth, Partha.","n":"१२.७"},{"d":"मय्येव मन आधत्स्व मयि बुद्धिं निवेशय।\nनिवसिष्यसि मय्येव अत ऊर्ध्वं न संशयः॥","r":"Mayyeva mana adhatsva mayi buddhim niveshaya,\nNivasishyasi mayyeva ata urdhvam na samshayah.","m":"Fix your mind on me alone and let your understanding rest in me. From then on you will live in me; of this there is no doubt.","n":"१२.८"},{"d":"अथ चित्तं समाधातुं न शक्नोषि मयि स्थिरम्।\nअभ्यासयोगेन ततो मामिच्छाप्तुं धनञ्जय॥","r":"Atha chittam samadhatum na shaknoshi mayi sthiram,\nAbhyasayogena tato mamichchhaptum Dhananjaya.","m":"If you cannot hold your mind steadily on me, then seek to reach me through the yoga of regular practice, Dhananjay.","n":"१२.९"},{"d":"अभ्यासेऽप्यसमर्थोऽसि मत्कर्मपरमो भव।\nमदर्थमपि कर्माणि कुर्वन्सिद्धिमवाप्स्यसि॥","r":"Abhyase’pyasamartho’si matkarmaparamo bhava,\nMadarthamapi karmani kurvansiddhimavapsyasi.","m":"If you cannot even practise, make work done for me your highest aim. Even by doing your actions for my sake, you will reach perfection.","n":"१२.१०"},{"d":"अथैतदप्यशक्तोऽसि कर्तुं मद्योगमाश्रितः।\nसर्वकर्मफलत्यागं ततः कुरु यतात्मवान्॥","r":"Athaitadapyashakto’si kartum madyogamashritah,\nSarvakarmaphalatyagam tatah kuru yatatmavan.","m":"And if you cannot do even this, then take refuge in me, master yourself, and let go of the fruits of all your actions.","n":"१२.११"},{"d":"श्रेयो हि ज्ञानमभ्यासाज्ज्ञानाद्ध्यानं विशिष्यते।\nध्यानात्कर्मफलत्यागस्त्यागाच्छान्तिरनन्तरम्॥","r":"Shreyo hi jnanamabhyasajjnanaddhyanam vishishyate,\nDhyanatkarmaphalatyagastyagachchhantiranantaram.","m":"Knowledge is better than mere practice, and meditation better than knowledge. Better still is letting go of the fruits of action, for peace follows at once.","n":"१२.१२"},{"d":"अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च।\nनिर्ममो निरहङ्कारः समदुःखसुखः क्षमी॥","r":"Adveshta sarvabhootanam maitrah karuna eva cha,\nNirmamo nirahankarah samaduhkhasukhah kshami.","m":"One who hates no being, who is friendly and compassionate, free of possessiveness and ego, the same in pain and pleasure, and forgiving,","n":"१२.१३"},{"d":"सन्तुष्टः सततं योगी यतात्मा दृढनिश्चयः।\nमय्यर्पितमनोबुद्धिर्यो मद्भक्तः स मे प्रियः॥","r":"Santushtah satatam yogi yatatma dridhanishchayah,\nMayyarpitamanobuddhiryo madbhaktah sa me priyah.","m":"always content, steady in yoga, self-controlled and firm in resolve, with mind and understanding offered to me: that devotee is dear to me.","n":"१२.१४"},{"d":"यस्मान्नोद्विजते लोको लोकान्नोद्विजते च यः।\nहर्षामर्षभयोद्वेगैर्मुक्तो यः स च मे प्रियः॥","r":"Yasmannodvijate loko lokannodvijate cha yah,\nHarshamarshabhayodvegairmukto yah sa cha me priyah.","m":"One who troubles no one and is not troubled by anyone, who is free from elation, envy, fear and anxiety, is dear to me.","n":"१२.१५"},{"d":"अनपेक्षः शुचिर्दक्ष उदासीनो गतव्यथः।\nसर्वारम्भपरित्यागी यो मद्भक्तः स मे प्रियः॥","r":"Anapekshah shuchirdaksha udasino gatavyathah,\nSarvarambhaparityagi yo madbhaktah sa me priyah.","m":"One who expects nothing, is pure and capable, impartial and untroubled, and has given up all self-centred undertakings: that devotee is dear to me.","n":"१२.१६"},{"d":"यो न हृष्यति न द्वेष्टि न शोचति न काङ्क्षति।\nशुभाशुभपरित्यागी भक्तिमान्यः स मे प्रियः॥","r":"Yo na hrishyati na dveshti na shochati na kankshati,\nShubhashubhaparityagi bhaktimanyah sa me priyah.","m":"One who neither rejoices nor hates, neither grieves nor craves, and has let go of both good and bad outcomes, full of devotion, is dear to me.","n":"१२.१७"},{"d":"समः शत्रौ च मित्रे च तथा मानापमानयोः।\nशीतोष्णसुखदुःखेषु समः सङ्गविवर्जितः॥","r":"Samah shatrau cha mitre cha tatha manapamanayoh,\nShitoshnasukhaduhkheshu samah sangavivarjitah.","m":"One who is the same to friend and foe, in honour and in insult, in cold and heat, in pleasure and pain, and free from attachment,","n":"१२.१८"},{"d":"तुल्यनिन्दास्तुतिर्मौनी सन्तुष्टो येन केनचित्।\nअनिकेतः स्थिरमतिर्भक्तिमान्मे प्रियो नरः॥","r":"Tulyanindastutirmauni santushto yena kenachit,\nAniketah sthiramatirbhaktimanme priyo narah.","m":"who takes blame and praise alike, speaks little, is content with whatever comes, is not bound to any home, steady of mind and full of devotion: that person is dear to me.","n":"१२.१९"},{"d":"ये तु धर्म्यामृतमिदं यथोक्तं पर्युपासते।\nश्रद्दधाना मत्परमा भक्तास्तेऽतीव मे प्रियाः॥","r":"Ye tu dharmyamritamidam yathoktam paryupasate,\nShraddadhana matparama bhaktaste’tiva me priyah.","m":"And those who follow this nectar of dharma just as I have taught it, with faith, holding me as their highest goal: those devotees are dearer to me than all.","n":"१२.२०"},{"d":"ॐ तत्सदिति श्रीमद्भगवद्गीतासूपनिषत्सु ब्रह्मविद्यायां योगशास्त्रे श्रीकृष्णार्जुनसंवादे भक्तियोगो नाम द्वादशोऽध्यायः॥","r":"Om tat sat. Iti Shrimad Bhagavad Gitasu Upanishatsu Brahmavidyayam Yogashastre Shri Krishnarjuna samvade Bhaktiyogo nama dvadasho’dhyayah.","m":"Om, that is the truth. So ends the twelfth chapter, the Yoga of Devotion, in the dialogue between Shri Krishna and Arjun, the Upanishad of the Gita, the knowledge of Brahman and the scripture of yoga.","n":"इति"}],"intro":"Arjun asks who knows yoga best: those who worship Krishna in his personal form, or those who meditate on the formless. Krishna answers, offers easier paths for those who find it hard, and ends with a portrait of the devotee he loves."},{"n":13,"d":"क्षेत्रक्षेत्रज्ञविभागयोग","r":"Kshetra Kshetragya Vibhag Yog","en":"The field and the knower of the field","count":34},{"n":14,"d":"गुणत्रयविभागयोग","r":"Gunatraya Vibhag Yog","en":"The three gunas","count":27},{"n":15,"d":"पुरुषोत्तमयोग","r":"Purushottam Yog","en":"The Supreme Person","count":20,"verses":[{"d":"ऊर्ध्वमूलमधःशाखमश्वत्थं प्राहुरव्ययम्।\nछन्दांसि यस्य पर्णानि यस्तं वेद स वेदवित्॥","r":"Urdhvamoolamadhahshakhamashvattham prahuravyayam,\nChhandamsi yasya parnani yastam veda sa vedavit.","m":"They speak of an eternal ashvattha tree with its roots above and its branches below, whose leaves are the Vedic hymns. Whoever knows this tree knows the Vedas.","n":"१५.१","sp":{"d":"श्रीभगवानुवाच","r":"The Lord said"}},{"d":"अधश्चोर्ध्वं प्रसृतास्तस्य शाखा गुणप्रवृद्धा विषयप्रवालाः।\nअधश्च मूलान्यनुसन्ततानि कर्मानुबन्धीनि मनुष्यलोके॥","r":"Adhashchordhvam prasritastasya shakha gunapravriddha vishayapravalah,\nAdhashcha moolanyanusantatani karmanubandhini manushyaloke.","m":"Its branches spread below and above, fed by the gunas, with the objects of the senses as their buds. Below, in the human world, its roots spread out, binding beings to action.","n":"१५.२"},{"d":"न रूपमस्येह तथोपलभ्यते नान्तो न चादिर्न च सम्प्रतिष्ठा।\nअश्वत्थमेनं सुविरूढमूलमसङ्गशस्त्रेण दृढेन छित्त्वा॥","r":"Na roopamasyeha tathopalabhyate nanto na chadirna cha sampratishtha,\nAshvatthamenam suviroodhamoolamasangashastrena dridhena chhittva.","m":"Its real form cannot be seen here, nor its end, nor its beginning, nor what it stands on. Cutting down this deep-rooted tree with the strong axe of detachment,","n":"१५.३"},{"d":"ततः पदं तत्परिमार्गितव्यं यस्मिन्गता न निवर्तन्ति भूयः।\nतमेव चाद्यं पुरुषं प्रपद्ये यतः प्रवृत्तिः प्रसृता पुराणी॥","r":"Tatah padam tatparimargitavyam yasmingata na nivartanti bhuyah,\nTameva chadyam purusham prapadye yatah pravrittih prasrita purani.","m":"one should seek that state from which there is no return, saying: “I take refuge in that first Person from whom this ancient stream of creation flows.”","n":"१५.४"},{"d":"निर्मानमोहा जितसङ्गदोषा अध्यात्मनित्या विनिवृत्तकामाः।\nद्वन्द्वैर्विमुक्ताः सुखदुःखसंज्ञैर्गच्छन्त्यमूढाः पदमव्ययं तत्॥","r":"Nirmanamoha jitasangadosha adhyatmanitya vinivrittakamah,\nDvandvairvimuktah sukhaduhkhasanjnairgachchhantyamoodhah padamavyayam tat.","m":"Free from pride and delusion, having conquered attachment, always dwelling on the Self, with desires stilled and released from the opposites called pleasure and pain, the wise reach that eternal state.","n":"१५.५"},{"d":"न तद्भासयते सूर्यो न शशाङ्को न पावकः।\nयद्गत्वा न निवर्तन्ते तद्धाम परमं मम॥","r":"Na tadbhasayate suryo na shashanko na pavakah,\nYadgatva na nivartante taddhama paramam mama.","m":"No sun, moon or fire lights that place. Those who reach it never return: that is my supreme home.","n":"१५.६"},{"d":"ममैवांशो जीवलोके जीवभूतः सनातनः।\nमनःषष्ठानीन्द्रियाणि प्रकृतिस्थानि कर्षति॥","r":"Mamaivamsho jivaloke jivabhootah sanatanah,\nManahshashthanindriyani prakritisthani karshati.","m":"An eternal part of me becomes the living soul in the world of beings, and draws to itself the five senses and the mind, which belong to nature.","n":"१५.७"},{"d":"शरीरं यदवाप्नोति यच्चाप्युत्क्रामतीश्वरः।\nगृहीत्वैतानि संयाति वायुर्गन्धानिवाशयात्॥","r":"Shariram yadavapnoti yachchapyutkramatishvarah,\nGrihitvaitani samyati vayurgandhanivashayat.","m":"When the soul, the master of the body, takes up a body or leaves it, it carries these along, as the wind carries scents from flowers.","n":"१५.८"},{"d":"श्रोत्रं चक्षुः स्पर्शनं च रसनं घ्राणमेव च।\nअधिष्ठाय मनश्चायं विषयानुपसेवते॥","r":"Shrotram chakshuh sparshanam cha rasanam ghranameva cha,\nAdhishthaya manashchayam vishayanupasevate.","m":"Presiding over hearing, sight, touch, taste and smell, and over the mind, it experiences the objects of the senses.","n":"१५.९"},{"d":"उत्क्रामन्तं स्थितं वापि भुञ्जानं वा गुणान्वितम्।\nविमूढा नानुपश्यन्ति पश्यन्ति ज्ञानचक्षुषः॥","r":"Utkramantam sthitam vapi bhunjanam va gunanvitam,\nVimoodha nanupashyanti pashyanti jnanachakshushah.","m":"The deluded do not see it leaving the body, staying in it, or enjoying the world through the gunas. Those with the eye of wisdom see it.","n":"१५.१०"},{"d":"यतन्तो योगिनश्चैनं पश्यन्त्यात्मन्यवस्थितम्।\nयतन्तोऽप्यकृतात्मानो नैनं पश्यन्त्यचेतसः॥","r":"Yatanto yoginashchainam pashyantyatmanyavasthitam,\nYatanto’pyakritatmano nainam pashyantyachetasah.","m":"Yogis who strive see it dwelling within themselves; but the unprepared and unaware do not see it, even when they try.","n":"१५.११"},{"d":"यदादित्यगतं तेजो जगद्भासयतेऽखिलम्।\nयच्चन्द्रमसि यच्चाग्नौ तत्तेजो विद्धि मामकम्॥","r":"Yadadityagatam tejo jagadbhasayate’khilam,\nYachchandramasi yachchagnau tattejo viddhi mamakam.","m":"The light of the sun that brightens the whole world, and the light in the moon and in fire: know that light to be mine.","n":"१५.१२"},{"d":"गामाविश्य च भूतानि धारयाम्यहमोजसा।\nपुष्णामि चौषधीः सर्वाः सोमो भूत्वा रसात्मकः॥","r":"Gamavishya cha bhootani dharayamyahamojasa,\nPushnami chaushadhih sarvah somo bhootva rasatmakah.","m":"Entering the earth, I hold up all beings with my strength; becoming the moon, full of sap, I nourish every plant.","n":"१५.१३"},{"d":"अहं वैश्वानरो भूत्वा प्राणिनां देहमाश्रितः।\nप्राणापानसमायुक्तः पचाम्यन्नं चतुर्विधम्॥","r":"Aham vaishvanaro bhootva praninam dehamashritah,\nPranapanasamayuktah pachamyannam chaturvidham.","m":"Becoming the digestive fire in the bodies of living beings, joined with the in-breath and out-breath, I digest the four kinds of food.","n":"१५.१४"},{"d":"सर्वस्य चाहं हृदि सन्निविष्टो मत्तः स्मृतिर्ज्ञानमपोहनं च।\nवेदैश्च सर्वैरहमेव वेद्यो वेदान्तकृद्वेदविदेव चाहम्॥","r":"Sarvasya chaham hridi sannivishto mattah smritirjnanamapohanam cha,\nVedaishcha sarvairahameva vedyo vedantakridvedavideva chaham.","m":"I am seated in the hearts of all; from me come memory, knowledge and their loss. I alone am what all the Vedas seek to know; I am the author of the Vedanta and the knower of the Vedas.","n":"१५.१५"},{"d":"द्वाविमौ पुरुषौ लोके क्षरश्चाक्षर एव च।\nक्षरः सर्वाणि भूतानि कूटस्थोऽक्षर उच्यते॥","r":"Dvavimau purushau loke ksharashchakshara eva cha,\nKsharah sarvani bhootani kootastho’kshara uchyate.","m":"There are two persons in this world, the perishable and the imperishable. All beings are perishable; the unchanging one is called imperishable.","n":"१५.१६"},{"d":"उत्तमः पुरुषस्त्वन्यः परमात्मेत्युदाहृतः।\nयो लोकत्रयमाविश्य बिभर्त्यव्यय ईश्वरः॥","r":"Uttamah purushastvanyah paramatmetyudahritah,\nYo lokatrayamavishya bibhartyavyaya ishvarah.","m":"But there is another, the highest Person, called the Supreme Self: the eternal Lord who enters the three worlds and sustains them.","n":"१५.१७"},{"d":"यस्मात्क्षरमतीतोऽहमक्षरादपि चोत्तमः।\nअतोऽस्मि लोके वेदे च प्रथितः पुरुषोत्तमः॥","r":"Yasmatksharamatito’hamaksharadapi chottamah,\nAto’smi loke vede cha prathitah purushottamah.","m":"Because I am beyond the perishable and higher even than the imperishable, I am known in the world and in the Veda as Purushottam, the Supreme Person.","n":"१५.१८"},{"d":"यो मामेवमसम्मूढो जानाति पुरुषोत्तमम्।\nस सर्वविद्भजति मां सर्वभावेन भारत॥","r":"Yo mamevamasammoodho janati purushottamam,\nSa sarvavidbhajati mam sarvabhavena Bharata.","m":"Whoever, free from delusion, knows me as the Supreme Person knows everything, and worships me with their whole being, Bharata.","n":"१५.१९"},{"d":"इति गुह्यतमं शास्त्रमिदमुक्तं मयानघ।\nएतद्बुद्ध्वा बुद्धिमान्स्यात्कृतकृत्यश्च भारत॥","r":"Iti guhyatamam shastramidamuktam mayanagha,\nEtadbuddhva buddhimansyatkritakrityashcha Bharata.","m":"So I have given you this most secret teaching, sinless one. Whoever understands it becomes truly wise and has done all there is to do, Bharata.","n":"१५.२०"},{"d":"ॐ तत्सदिति श्रीमद्भगवद्गीतासूपनिषत्सु ब्रह्मविद्यायां योगशास्त्रे श्रीकृष्णार्जुनसंवादे पुरुषोत्तमयोगो नाम पञ्चदशोऽध्यायः॥","r":"Om tat sat. Iti Shrimad Bhagavad Gitasu Upanishatsu Brahmavidyayam Yogashastre Shri Krishnarjuna samvade Purushottamayogo nama panchadasho’dhyayah.","m":"Om, that is the truth. So ends the fifteenth chapter, the Yoga of the Supreme Person, in the dialogue between Shri Krishna and Arjun, the Upanishad of the Gita, the knowledge of Brahman and the scripture of yoga.","n":"इति"}],"intro":"Krishna describes the world as an upside-down tree to be cut down with detachment, explains how the soul moves from body to body, and reveals himself as Purushottam, the Supreme Person beyond both the perishable and the imperishable. Many ashrams and families recite this chapter before meals."},{"n":16,"d":"दैवासुरसम्पद्विभागयोग","r":"Daivasur Sampad Vibhag Yog","en":"The divine and the demonic","count":24},{"n":17,"d":"श्रद्धात्रयविभागयोग","r":"Shraddhatraya Vibhag Yog","en":"The three kinds of faith","count":28},{"n":18,"d":"मोक्षसंन्यासयोग","r":"Moksha Sanyas Yog","en":"Freedom through renunciation","count":78}]}]};
